// 第 185—200 节：逐节自译，解释与补充例子为本站编写。
(() => {
 const add=(lesson,essay)=>{window.LESSONS.push(lesson);window.ESSAYS[lesson.id]=essay;};
 // 以下紧凑字段仅用于内容维护，输出仍采用全站统一的数据结构。
 const study=c=>add({id:c.id,short:c.short,title:c.title,subtitle:c.sub,tags:c.tags,connection:c.link,translation:c.text},{core:c.core,coreMore:c.more,closeReading:c.quotes,problem:c.problem,conceptTitle:c.heading,concepts:c.concepts,table:{headers:c.headers,rows:c.rows},argument:c.steps,opposition:c.against,perspectives:c.views,cautions:c.warn,summary:c.summary});
 add({id:185,short:'加二怎样继续',title:'学生跨过一千后，为什么开始每次加四？',subtitle:'相同的过去表现，并没有替我们描述所有未来的应用。',tags:['规则','数列','训练'],connection:'回到第143节的教学；第186节追问怎样判定下一步正确。',translation:['现在回到我们的例子（第143节）。按照通常标准判断，学生如今掌握了基本数列。我们又教他写其他基数序列，使他能根据“+n”形式的命令，写出0、n、2n、3n等等这样的序列；所以，按“+1”的命令就写出基本数列。假定我们的练习和理解抽查都只做到1000以内。','现在让学生把一个数列，例如“+2”，继续到1000以上；他却写：1000、1004、1008、1012。','我们说：“看看你在做什么！”他不明白。我们说：“你应当加二呀；看看你怎么开头的！”他回答：“是啊！这难道不对吗？我以为就应该这样做。”或者设想，他指着数列说：“我不是按同一种方式继续了吗！”这时，重复旧解释和例子，说“难道你看不见……”对我们并无帮助。在这种情况下，我们也许会说：这个人根据我们的解释，自然而然地把那道命令理解成我们所理解的“到1000为止总加2，到2000为止加4，到3000为止加6，等等”。这个情形类似于：有人面对手的指示动作，自然沿着从指尖到手腕的方向看，而不是朝指尖所向看。']},{core:'第185节把理解的标准放在一个新的应用场合中检验。学生此前通过了通常考查，但跨过1000后用另一种方式继续，而且自认仍在照旧。作者不是宣布加四也符合我们通常的加二规则，而是让我们检查：旧解释、内心确信和有限实例怎样与继续做下去相连。',coreMore:'例子的力量来自分歧并非一个被学生承认的笔误。他并不接受“你只是没看清”的纠正。因而，把过去的解释再说一遍，未必就能完成新的教学工作。接下来要澄清的，是我们怎样使用“相同”“正确”“本来就是这个意思”等表达。',closeReading:[['按照通常标准判断','开头明确承认学生已经掌握基本数列。这不是先宣布一切理解都是幻觉。我们通常能够合理判断掌握，而在新情况下仍可能遇到需要重新说明的差异。把这种判断与绝无任何异常可能的保证等同，才会给理解加上一项无法完成的任务。'],['我不是按同一种方式继续了吗','相同方式不是由学生的确信自行决定的，也不能靠教师更大声地重复相同二字来说明。双方把不同接续叫作照旧，这让“同一种方式”的实际判断背景成为问题。作者要求展示这种背景，而非废除正常加法的标准。'],['重复旧解释和例子','旧解释本来可以有效，这里却设想其作用出现边界。不是每次教学都需要无穷解释，而是任何解释的文字都不能在脱离已学反应的情况下，像魔法一样保证预期效果。重复有时有用，本例特意让它暂时不起作用。'],['沿着从指尖到手腕的方向看','指示手势的对照把数字分歧转成容易看见的方向差异。我们习惯朝指尖看，不等于手的外形独自向每个观察者发布唯一命令。这个比较说明训练与自然反应的位置，并不使反向看成为通常指路的正确做法。']],problem:['教师很容易说，自己早就把以后每一步告诉学生了，因为“加二”已经包括一切。学生却在未练过的区域给出另一种接续。困难不是计算1000加2有多难，而是如何说明一句命令拥有其熟悉作用。作者用极端例子，把平常不被注意的教学背景显露出来。','先前的有限表现确实给了我们判断理解的依据，却不是一部在脑中预演无限未来的影片。若为了保持判断绝对无误，声称真正理解一定已完成全部未来步骤，就从教学标准转到了一个额外心理神话。接下来的几节正会检查这种跳跃。','本站补充：学习者照着表格抄写日期，过去总与我们一致，新月份却采用另一种排列。我们会根据具体错误调整教学，而不是立即得出所有日期排列等价。这个补充只帮助区分判断可以有根据与判断预先穷尽全部情形，不能替代原文数列的详细对照。'],conceptTitle:'有限考查与继续应用',concepts:['理解考查是在活动中进行的：教师展示，学生尝试，错误被纠正，新的例子被加入。它能充分支持“已经会了”的通常判断。若把充分理解改成先证明不可能存在任何不同接续，便把实际考查换成一个脱离教学用途的绝对要求。','学生的自然反应不是个人任性的同义词。他可以认真、自信、稳定地偏离我们。这使因果心理解释和规范判断必须分开：说明他为什么这么写，并不等于说他写得符合我们的命令；坚持命令有标准，也不等于已经说明标准如何在训练中发挥作用。'],table:{headers:['情形','可以判断','不能直接推出'],rows:[['1000以内考查通过','通常标准下已经掌握','未来异常已被逐一排除'],['1000以后每次加4','偏离我们通常的加2','所有接续都同样正确'],['反向理解手势','自然反应可能不同','方向无需教学背景']]},argument:['先承认正常掌握，避免把讨论偷换成学生根本未学过。例子因而针对的是规则的继续应用，而非是否存在初级教学。','再设定稳定且自认正确的偏离，使简单归因于走神或笔误的解释失效。旧例子的再现也未被设成自动有效。','最后用指示手势比较，让“照旧”依赖熟悉做法这一点能够被看见。第186节将从这里追问正确下一步的判定，而非立即建立另一套数学。'],opposition:['本节反对把过去解释看作已经在一种特殊心理空间里列出了无限步骤。这样说只是把需要理解的规则效力搬进心里，并没有说明它。','它也反对以教学可以异常为由取消通常正确性。学生的不接受值得描述，却不因此取得改写我们加法标准的权力。'],perspectives:[['从教学看','有限练习的价值在其具体用途，不在于构成无例外的未来契约。教师可以合理判断已经理解，也可以在新异常出现时重新指导。'],['从数学看','1000之后通常应写1002并未受到一次反向计算的推翻。需要澄清的是命令与应用的关系，不能把思想实验当成加法反例。'],['从语言看','“相同方式”与“应该”有学习和纠错背景。词面相同不能代替对这一背景的展示，双方确信相同也不能消除实际差别。']],cautions:[['不是无限怀疑所有学习','本例刻意突出一种可能分歧，不要求平常每次说会了都先证明无穷未来。'],['不是多数投票决定算术','习俗与训练的作用不是随时通过表决更改正确答案。这里要说明标准如何在实际活动中运作。'],['不是笨学生的心理诊断','学生也许没有失神或恶意。这个设定用来澄清概念联系，并非一项关于学习障碍的经验理论。']],summary:'先前掌握与新的偏离可以并列考察，规则的作用不能由确信或无限心理预演解释。'});
study({id:186,short:'正确下一步的判定',title:'每一步都需要新的直觉吗？',sub:'先问“正确”如何工作，再问意向怎样保证未来。',tags:['规则','直觉','决定'],link:'承接185节数列分歧；187节检查“当时已经知道”的语法。',text:['“所以，你说的归根到底是：要正确遵从‘+n’这道命令，每一步都需要一种新的洞察——直觉。”——正确遵从！那么，怎样决定某个位置上的正确一步是什么？“正确的一步，就是与命令原本的意思一致的那一步。”——因此，你发出“+2”命令时，就意指他应在1000后写1002；那么，你当时也意指他应在1866后写1868，在100054后写100036，等等——意指无穷多个这样的句子吗？〔校读说明：100054后接100036为本数字底本如此；若按通常加2，应为100056。〕“不是；我的意思是，他每写出一个数，就应接着写这个数之后第二个数；所有那些句子，都在各自的位置从这里推出。”——可问题恰是：在任一位置，什么从那个句子推出。也可以说，什么应被我们在任一位置叫作与那个句子‘一致’，也就是与当时赋予句子的意思一致，无论那个意思究竟是什么。说每一点需要一种新直觉，倒不如近乎说：每一点需要一个新决定。'],core:'第186节拒绝用“新的直觉”填补规则与应用之间的空隙。诉诸原本意向，也必须说明意向怎样在具体位置规定一致。把无穷个未来答案塞进一次意指并无帮助；再给一句总命令，仍不能绕过它怎样被继续使用。',more:'末尾“新决定”带有“近乎”的限定，不是宣布算术每一步由个人随意选择。它动摇的是把直觉当成一个独立、不会错的判定机关的想象。作者把问题从心理保证重新放回我们怎样决定与规则一致的用法。',quotes:[['怎样决定某个位置上的正确一步是什么','提问先针对“正确”的标准。若说直觉会告诉我们正确答案，却未交代怎样判定这个直觉正确，解释就只是转了一个圈。直觉可能伴随熟练判断，但不能仅凭它被体验为明白，就取得规范权威。这里的回问防止把内心确信当作规则本身。'],['意指无穷多个这样的句子吗','我们当然能够发出涉及无穷数列的命令，而不必实际想遍所有数。作者针对的是把一次意向说成已经逐条完成了那些过渡的说法。有限意识里未出现无穷答案，并不直接证明规则没有作用；它说明应换一种方式描述规则的作用。'],['问题恰是：在任一位置，什么从那个句子推出','一句“总写第二个后继数”可作解释，却不能在当前争论中自动成为最后根基。对方所不接受的正是这种表达如何继续。用更概括的句子替代原句，若保留同样的应用问题，就没有结束考察。这里不是否定解释可以有用，而是限制它被赋予的独立保证功能。'],['倒不如近乎说：每一点需要一个新决定','“近乎”不能删去。作者在比较两种诱人说法的偏差，没有建立一种每一步凭空选择的数学理论。新位置确实要被走出，不能只靠声称过去已经完成；但实际如何走，仍有训练、算例和正常判断的背景。']],problem:['学生写出与教师不同的后继数之后，容易产生一种补救：规则只是框架，另有直觉替我们在每点选择答案。这把困难藏到一项心理能力里，却没有说明它怎样区别正确与错误。作者因而先追问正确遵从，而不急着接受“直觉”这个解释名称。','另一种补救是说，真正命令不是纸上的符号，而是教师当时所意指的内容。若这内容被设想成所有过渡的总和，就要回答教师当时是否已逐一想到它们。若改说只是一个概括的后继规则，则又遇到后继规则怎样应用的问题。','本站补充：给一个不懂循环规则的人补写“每次都照前一步做”，并不会只凭“每次”两个字使教学完成。这个例子不是计算机执行机制的理论；它说明把实际掌握省略后，再增加全称措辞，无法单独补上被省略的联系。'],heading:'一致不是由意向标签自行保证',concepts:['规则与意向可以在日常表达中相连。教师能够说“我的意思是加二”，并纠正学生。但如果把“原来的意思”安置为一个脱离所有用法的隐藏对象，再要求这个对象独立裁定每一步，就需要说明该对象怎样被识别、怎样发生规范作用。给它命名，不等于完成说明。','“推出”也是一种有使用背景的表达。我们在计算和证明中学会什么算推出，遇到某种错误会如何改正。本节没有取消推导，而是反对在应用本身成为问题时，单靠说“这已经从规则推出”就当成已给出解答。这里的语法澄清与算术推导各有工作。'],headers:['补救说法','尚待说明','不能当作结论'],rows:[['直觉给出答案','怎样区分正确直觉','感觉确定即正确'],['意向含有全部过渡','无穷过渡如何被意指','意识已经逐项演算'],['一般句子推出答案','什么算符合该句','更抽象便无须应用']],steps:['先把反对者的直觉说转成关于正确性的问题，显示原先的解释尚未给出独立标准。','再追问一次意向是否已经包含无穷个具体句子，从而暴露心理预演的负担。','最后考察概括规则能否补救，并以带限定的新决定说松动既有图景。下一节会保留普通的“我当时就知道”，同时去除它的超常解释。'],against:['它反对把规则作用交给一个神秘直觉机关，也反对把一次意识变成已经完成无穷工作的容器。两者都增加了一个心理名称，却未说明正常推导如何被掌握。','它不反对日常使用“直觉”“意思”“推出”。这些说法可以在具体数学活动中发挥作用；受到质疑的是把它们提升为全部使用之外的最后保证。'],views:[['从论证看','当一个词本身正在被追问时，再用这个词复述保证，不能代替说明。所谓一致，需要通过相关的判断活动来展开。'],['从数学看','对象数列是无穷的，不意味着发令者的意识必须实际无穷。应区分命令的范围与心理事件的时长，不能由后者有限便否定前者。'],['从教学看','给出一般解释常有帮助，但学习者怎样接续仍须观察。解释的普遍语气和解释在教学中的实际效果，不属于同一层次的事实。']],warn:[['不是每步随意重选','末句是比较性的诊断，不能取代原有规则标准。它没有赋予个人随时决定加法结果的权力。'],['不是数学依赖神秘直觉','开头的直觉说属于异议，作者先要求解释其正确性，不是赞同一种新的心理基础。'],['不是原数字可静默修正','底本个别数字与加二不符，本站已标明校读。保留来源与通常计算的区别，有助于避免把转录异常误认作论证要点。']],summary:'直觉和原本意向都不能只凭名称替每个新位置提供规则一致性的解释。'});
study({id:187,short:'当时已经知道',title:'“我早就知道答案”，一定是在回忆一个念头吗？',sub:'用反事实的回答能力，澄清关于过去意向的说法。',tags:['知道','意指','反事实'],link:'承接186节无穷过渡的疑问；188节揭示心灵提前飞越的图像。',text:['“可是，我发出命令时，就已经知道，他应该在1000后写1002！”——当然；你甚至可以说，你当时就意指这个。只是别让“知道”和“意指”这些词的语法误导你。因为，你并不是说，当时曾想到从1000到1002这个过渡；即使想到这一个，也没有想到其他过渡。你的“我当时已经知道……”大致意味着：“如果当时有人问我，他应该在1000后写哪个数，我就会回答‘1002’。”我对此并不怀疑。这项设想，大致类似于：“如果他当时落水，我就会跟着跳下去。”那么，你的观念错在哪里呢？'],core:'第187节保留“我当时已经知道”的正常用途，同时拒绝把它读成“我当时已想过全部答案”。我们可以依据已有的掌握，回顾性地说自己当时会给出某个回答；这与回忆当时真实发生过一次具体思考不同。',more:'作者并不怀疑教师当时会回答1002。他承认这一点，才进一步追问错误的哲学图像在哪里。澄清不是把普通的知识归属取消，而是阻止普通说法被改写成一个关于无限内在过程的报告。',quotes:[['你甚至可以说，你当时就意指这个','这句许可很重要。维特根斯坦没有用禁用词语来解决问题。意指未来答案可以是正常表达，其含义要由使用场合说明。若先把日常句子一律判错，就会遗漏真正问题：我们如何被同一表达引向一种过强的心理解释。'],['你并不是说，当时曾想到从1000到1002这个过渡','知道与想到不能不经检查就等同。人可知道乘法表，却没有每时每刻背诵。这里仍针对数列命令：当时能正确回答某一新问题，与当时曾在意识里明确演算该题，属于不同描述。'],['如果当时有人问我','这是一个反事实表达：所说条件没有实际发生，仍可依当时的掌握作出有根据的判断。它不是隐蔽记忆，也不是一项关于脑中所有内容的清单。作者用这个转述，让“已经”从神秘预演回到熟悉能力。'],['如果他当时落水','救人的类比不用于证明教师计算能力，而是说明有关过去的反事实说法本就有正常位置。我们不因为人说会跳水救人，就要求他当时已经实际跳过一次。关于回答数列问题的说法也不能仅凭过去时态被改写成已发生动作。']],problem:['反对者觉得，若当时没有确定一切，将来正确答案便只是一种偶然结果。为排除偶然，他强调自己当时已经知道。这句话本可合理，但若其中的“已经”被当作对完成事件的报告，便容易重建前节的无限心理演算。','理解这句话，需要分清当时实际发生了什么与当时已经具备什么能力。教师可能只发出加二命令，没有想1000这个数。我们仍能合理地说他当时知道1000后的正确答案，因为他已掌握相关计算。这种知识并不需要那次思考实际在场。','本站补充：熟练说话者昨天没有想到某个词，仍可以说昨天就懂这个词。依据可以是他长期的语言掌握，而非找出昨天心里这个词的影像。这个补充用于展示同类语法差异，不将本节知识说明普遍还原成行为预测。'],heading:'知识归属与事件回忆',concepts:['事件回忆回答的是，那一刻是否出现了这个念头；知识归属则可以涉及一个人当时能够怎样作答。二者有时共同成立，但前者不是后者一律必需的组成部分。把所有知识归属都解释成微小事件，就会要求在心里寻找原本未必发生的东西。','反事实判断可以有强弱之分，也可能被修正。作者此处并不需要证明所有反事实都不会错；他只要让我们承认一种普通用法，就足以松动“已经知道必等于已经想到”的必然联系。例子中的确信不靠无限预演来支撑，也不因此毫无根据。'],headers:['表达','通常所作的事','不必包含'],rows:[['当时已经知道1002','归属已有计算掌握','实际想到1000'],['如果被问就会回答','说明当时会怎样继续','回放未发生的对话'],['如果落水我会救他','作出过去反事实判断','当时已跳入水中']],steps:['首先明确同意教师的日常主张，避免把讨论转成教师是否识数的怀疑。','然后拆开知道、意指与实际想到的关系：一个正确未来答案不必对应过去的一次被记忆的演算。','最后用救人反事实展示相似语法，让读者能辨认一种无需神秘心灵对象的解释。末尾问题并未封闭讨论，而将其交给188节的图像诊断。'],against:['本节反对把语法上的过去完成误当成心理上已经完成一切。一个表达怎样合法回顾过去，与意识中曾经有哪些内容，需要各自说明。','它不反对关于自身过去的合理判断，也不宣布我们只能等行为发生后才能知道自己会什么。那样会走向与原文明确许可相反的极端。'],views:[['从第一人称看','作者没有剥夺第一人称的通常权威。教师可说自己当时知道，也可说本来就意指那个答案；但这不把意指变成不受说明的超常过程。'],['从时间看','能力在某时存在，与一次表现于某时发生，是两种时间结构。把时间词用在两者身上，不意味着两者必定是同一种事件。'],['从澄清看','把一句话换成另一种日常表述，有时比追寻隐藏实体更有帮助。反事实转述并不构成唯一知识理论，而是回应本段特定的误导。']],warn:[['不是知识只是猜测','反事实可以基于扎实掌握。未曾实际想过该题，不意味回答毫无根据。'],['不是记忆没有价值','人当然也可回忆实际想到的过渡。作者只说这不是所有“当时已经知道”的必要结构。'],['不是已经解决所有意向问题','末尾仍问错误观念在哪里。下一节将说明心灵飞越的比喻如何利用了这些表达。']],summary:'“当时已经知道”可以说明已有掌握，不必报告当时已逐项想到未来答案。'});
study({id:188,short:'心灵提前飞越',title:'意指一道命令，难道是在心里先做完无穷步？',sub:'看清一种比喻怎样冒充理解的机制。',tags:['意指','预先决定','图像'],link:'承接187节保留的日常知道；189节检查公式决定过渡的实际说法。',text:['这里，我首先想说：你的观念是，那次对命令的意指，已经以它自己的方式完成了所有那些过渡；意指时，你的心灵仿佛向前飞去，在你身体到达这个或那个位置之前，就做完了全部过渡。','所以，你倾向于这样说：“这些过渡其实已经做了；在我用书写、口说或思想作出它们之前，就已经做了。”于是，它们仿佛已经以一种独一无二的方式被预先确定、被预先把握，仿佛只有意指才能如此预先把握现实。'],core:'第188节把前面的误解描成心灵提前飞越：一次意指仿佛已经以超常方式完成全部未来过渡。作者是在展示诱惑的形状，不是在揭示意向的真实运作。它把正常的预先规定夸张为已经发生，却没有交代这种发生是什么。',more:'心灵飞行的画面之所以诱人，是它似乎兼顾两个要求：未来尚未实际计算，但答案又已确定。问题是，用一种无从说明的特殊完成，把“尚未做”与“已经做”拼在一起，并没有解决规则怎样规定使用。',quotes:[['已经以它自己的方式完成了所有那些过渡','“以它自己的方式”像是补丁：我们承认没有书写或思考每步，却仍想保留全部已完成的说法。若不能给出这特殊方式的用法说明，它只是把困难重新命名。此处的“你的观念”明确标出被检查的对象。'],['你的心灵仿佛向前飞去','飞行不是经验心理学假说。它把数学中的预先规定空间化、动作化，使人仿佛看见一个先行者。作者用明显的画面，让我们反过来发现原先抽象说法也可能受同一种图景支配。'],['在我用书写、口说或思想作出它们之前','这排除了所有熟悉的完成方式，却继续使用完成一词。我们需要问，这个词在这里还有什么实际工作。否认有无穷心理步骤，不是证明规则不能定答案；被撤回的只是将规则效力等同于超前执行的模型。'],['只有意指才能如此预先把握现实','独一无二的表述容易让缺少比较对象看起来正是深度所在。可是没有可说明的比较，不能自行变成存在特殊过程的证据。后面191、192节还会检查这种不断加强措辞的冲动。']],problem:['我们可以预先规定一项工作怎么做，而不必已经做完工作。混乱始于把前一种关系说成后一种事件。数列无限，心灵便被赋予无限飞越的能力，好像这样就能说明有限命令如何规定无限应用。','若这是过程，应该能说它与其他过程有什么差别；若它不是任何熟悉过程，却仍被说成在特殊意义上做完，说明的任务就没有结束。意指这个日常词似乎承担了它本来未承担的机制保证，直到规则与使用的实际联系反被遮住。','本站补充：写一份路线安排，并不等于有一位隐形旅客已先走完全程。计划可以使后续行动有依据，但计划与执行不是因为都能说“完成”便具有同样结构。这个比喻仅供对照，不能拿有限路线代替无限数列的数学性质。'],heading:'规定未来与执行未来',concepts:['预先规定可以是设定规则、发出命令、登记约定；其效力要从人怎样学习和使用这些做法来说明。提前执行则是一种事件设想。本节显示把前者的确定性借用后者的图像，会产生一种没有明确实例却声势很强的混合表达。','意向并非因此成为空洞词语。我们仍可区分想加二与想加三，也可纠正错误理解。作者要求的改变，是不要将这种区分的规范作用全算到一个在意识中独立完成无穷步骤的东西身上。日常意向可以被保留，超常内在工程则需要拆开。'],headers:['说法','合理用途','误导性延长'],rows:[['已发出命令','后续工作已有要求','命令已执行全部步骤'],['本来想加二','说明所作计算','心灵曾飞越无限数列'],['未来答案被确定','在规则活动中可判断','答案像物件预存心中']],steps:['先为前节的错误观念提出一个可辨认的图像，让隐藏在抽象表达中的动作比喻出现。','再列出“已经做了”与尚未书写、说出、想到的并置，显示我们在保留什么，同时又排除了什么。','最后指出独特预先把握的说法。它提出的并非可检验说明，而是对说明方式的额外要求；下一节将转向“公式决定”怎样实际使用。'],against:['它反对以一个心理奇迹解释数学命令的效力。把心灵放在身体前方并无限加速，仍未说明什么算与命令一致。','它不反对规划、预见或提前规定，也不认为未来使用都不能确定。受到质疑的是把它们统一改画成已完成的内在演出。'],views:[['从图景看','一个比喻能够帮助说明，也能够限制思想。看见飞行比喻的来源，使人不必再为它寻找一件无形飞行器。'],['从规则看','规则的规范角色不是靠更早发生一次相同行动建立。若只有先做过才能规定，任何新应用都将失去解释。'],['从心理看','否认这幅无限飞越图像，不等于否认人会出现意向、感觉和想象。要分别描述实际体验与被体验承担的哲学任务。']],warn:[['不是作者赞成心灵飞越','整节介绍的是“你的观念”。把比喻摘成心理理论，会把诊断对象误当成结论。'],['不是未来完全无规定','从特殊完成不存在，不能推出规则无效。下一节正恢复决定这一表达的具体用途。'],['不是意指必须逐项列举','日常意指可以涉及无穷数列。需要撤回的恰是意指必已实际完成无穷项的要求。']],summary:'意指规则的确定性不需要被画成心灵已经跑完全部未来步骤。'});
study({id:189,short:'公式怎样决定',title:'公式决定答案，究竟是在说什么？',sub:'把教学中的确定与公式种类的区别分开。',tags:['公式','决定','用法'],link:'接188节心灵飞越的误解；190节考察公式怎样被意指。',text:['“可是，过渡难道不是由代数公式决定的吗？”——这个问题里有一个错误。','我们使用“过渡由公式……决定”这个表达。它怎样使用？例如，我们可以说，人经过教育、训练，学会使用公式y=x²，于是所有人把同一个数代入x时，总计算出同一个y。或者说：“这些人受到这样的训练：在‘+3’命令下，同一位置都作同一个过渡。”我们可以这样表达：命令“+3”为这些人完全决定了从一个数到下一个数的每次过渡。（这与另一些人相对：他们在这命令下不知道做什么；或者虽都十分肯定，却每人作不同反应。）','另一方面，我们可以对照不同种类的公式，以及与它们相应的不同使用方式、不同训练方式。我们把某类公式及其使用方式叫作“对给定x决定一个数y的公式”，把另一类叫作“对于给定x并不决定数y的公式”。y=x²属于前一类，y≠x²属于后一类。这样，“公式……决定一个数y”便是关于公式形式的陈述。此时还要区分：“我写的公式决定y”或者“这里有一个决定y的公式”，与“公式y=x²对给定x决定一个数y”这样的陈述。“那里有一个决定y的公式吗？”便意味着：“那里有这一类公式，还是那一类？”可是，“y=x²是不是对给定x决定y的公式？”这个问题应拿来做什么，并不立即清楚。例如，可以拿它问学生，考查他是否理解“决定”的用法；也可以是一道数学题，要求在某一系统内证明x只有一个平方。'],core:'第189节没有否定公式决定答案，而是区分“决定”的实际用法：它可以描述受训练者怎样稳定使用公式，也可以区分公式的数学形式。把这些用法混成一种神秘作用，再问公式是否真的决定，会制造一个没有明确任务的问题。',more:'开头说问题有错，不等于任何同样字面的提问都无意义。末尾明确给出教学考查和数学证明的场合。同一句话放进不同活动，可以成为不同问题；哲学混乱来自省略这些活动，却继续要求一个比它们更深的统一保证。',quotes:[['它怎样使用','这是方法上的转向。作者不去找公式背后放出答案的隐形机关，而是问人们用决定一词做哪些区分。列举用法不是用事实票决数学，而是澄清当前陈述究竟是一项行为描述、概念分类还是证明要求。'],['所有人把同一个数代入x时','共同训练的例子展示命令怎样在一群人中实际发挥确定作用。它不说只要大家同算就不会算错，更不把任意共识定义为数学真理。这里比较的是同一表达有稳定操作，与听者完全不知道如何做或各做各的。'],['关于公式形式的陈述','在既定数学用法中，等式与不等式承担不同限制。说某公式决定一个数，可以是在把它归入某种形式类别。此时标准涉及学过的数学区分，不是报告看见符号向一个未来答案施加了物理力量。'],['在某一系统内证明x只有一个平方','作者承认一个清楚的证明任务，防止读者把整段当成反数学宣言。证明可以重要，但它所在系统和要证的命题需要说清。不能把某一系统内的证明误当成完全脱离使用的决定之本质已经被发现。']],problem:['一句“公式决定答案”看似简单，却能在不同场合承担不同工作。若把它当成同一机制的报告，便会问符号本身如何控制所有未来行动。这个机制图像正承接前节心灵飞越，并不因从心灵换成公式就自动合理。','教学场合里，决定可以说明人们在命令下有一致而稳定的接续；数学场合里，它可以区分唯一给值的式子与留下多个可能值的限制。这两种陈述彼此关联，但所回应的问题不同，检验方式也不同。','本站补充：问“这份表能决定运费吗”，可能在查表是否列出唯一价格，也可能在问员工是否会按表办事。若连在问哪件事都不分，争论就容易把资料完备与实际执行混为一谈。这是补充比较，不是原文对公式的定义。'],heading:'行为中的确定与形式中的确定',concepts:['训练不是对数学的外在污染。一个符号被当作平方、加法或限制条件使用，离不开人如何学会这些操作。承认这一点，并不要求每个数学证明都附上一项心理学调查。数学可以在已掌握的技术中继续，哲学则考察我们对技术作出的概括有没有偷换。','公式类别的区分已经带着相应使用方式。单凭墨迹的形状，未指定符号怎样读、变量范围如何取，就无法获得全部数学内容。作者提到不同公式与不同训练同时出现，正是防止我们把形式看成一个不需要应用背景的自行运转实体。'],headers:['提问场合','“决定”的工作','相应检查'],rows:[['人们使用+3','说明稳定接续','看已学操作怎样进行'],['等式与不等式比较','区分公式种类','看给值条件与范围'],['课堂提问','检验词的掌握','看学生能否举例分类'],['系统内证明','提出数学任务','依系统规则证明']],steps:['先拒绝抽去用途的总问题。作者不是用否定取代肯定，而是要求先确定问题的工作。','再展示共同训练与公式类别这两组用法，说明同一表达不必指向一个同质的隐藏事实。','最后恢复清楚的提问场合：可以考学生，也可以要求证明。恢复用途使问题具体化，并未取消逻辑与数学的严格标准。'],against:['它反对把公式决定理解成一种独立于所有应用的神秘强制，也反对把人的一致行为与数学形式的分类直接合并。','它不反对公式的严格性、数学证明或教学评估。对抽象总问题的批评，不能升级为对每个具体数学问题的否定。'],views:[['从分类看','“这里有这种公式吗”与“这种公式有什么性质”可以是不同层次的提问。一个问眼前实例，一个问类型，不能只因都含决定二字就合并。'],['从训练看','不知道如何反应和每人各有一套自信反应，都与共同技术形成对照。确定性由此显出实践位置，而非被简化为某种感觉强度。'],['从数学看','证明任务需要明确系统。语法澄清可以指出任务被省略，却不能以此替数学完成证明，二者不应彼此僭越。']],warn:[['不是大家同意就定义正确','共同训练说明技术如何存在，不是随时以多数票改写算术。'],['不是符号形式无关紧要','本节恰保留公式形式的明确区分，只拒绝让形式在没有使用方式时自行携带一切。'],['不是所有决定问题都无意义','末尾给出两种有用问题。错误是把它们抽掉之后仍以为原问题不变。']],summary:'问公式是否决定答案，先要说清是在描述训练、区分形式，还是提出某个证明任务。'});
study({id:190,short:'公式意指的标准',title:'说“我是这个意思”，怎样看出你是什么意思？',sub:'把意指放回学会的符号操作。',tags:['意指','标准','符号'],link:'承接189节公式的不同用法；191节检查一下把握的更强说法。',text:['现在可以说：“公式被怎样意指，决定了应作哪些过渡。”那么，公式是怎样被意指的，标准是什么？例如，是我们一贯怎样使用它，以及别人教我们怎样使用它。','例如，某人使用一个我们不熟悉的记号，我们对他说：“如果你用‘x!2’意指x²，就得到这个y值；如果你用它意指2x，就得到那个。”——现在问自己：人怎样做到用“x!2”意指这一种或那一种？','所以，意指可以这样预先决定过渡。'],core:'第190节允许说意指决定公式的过渡，但要求交代判断意指的标准。标准可以在一贯使用与所受教学中找到。陌生记号可被用作平方或两倍，差别不是记号外形自带的，而要通过如何计算、解释和继续来体现。',more:'末句的“这样”回指本节给出的实践联系，不能删掉它，只留下意向可以神秘预定一切。作者不是撤回前面批评，而是在澄清之后恢复一个日常表达的有限而清楚的作用。',quotes:[['公式被怎样意指','这句话可以说，但不必把意指物化成公式背后另一件更真公式。若只是把纸面符号搬进头脑，同样的应用问题会再次出现。作者随后要求标准，是为了让这句话的用法可见。'],['标准是什么','标准不是造成意向的因果过程，而是我们凭什么在此说这个人想表达平方而非两倍。它可以包括解释、算例、教学和一贯继续的方式。不能只用“他内心有那个意思”重新复述问题。'],['我们一贯怎样使用它','一贯使用提供稳定联系，使陌生记号进入已掌握的计算。它不把所有偏离都视为改变意思；一次笔误仍可在一贯技术中被识别为错误。对持续背景的强调，反而使错误与另一种用法能够区分。'],['所以，意指可以这样预先决定过渡','“这样”限制了决定说的解释方向。前面展示的学习、比较与应用，是读懂末句的必要上下文。若把最后一句抽成内心超能力的证明，就会重新造出作者已经拆解的飞越图像。']],problem:['面对陌生记号，单看外形不能知道它在当前计算中当平方还是乘二。人们却仍能够使用新记号并说明自己的意思。这种实际可能性要求我们既不把意义归给墨迹自身，也不把意义交给一个不可检查的内在印章。','如果说一个人在心里用熟悉公式解释陌生符号，仍可追问他怎样理解熟悉公式。用更深一层符号解释，不可能只凭增加层数就把应用问题消除。实际教会与使用新记号，是需要重新展示的背景。','本站补充：在一种表格中，星号表示重复次数，在另一种表格中表示备注。查用法说明并看具体操作，可以解除歧义；无需设想星号内部储存两件私有意义。这个例子不定义原文记号，而是说明符号选择与操作背景的关系。'],heading:'意指不是没有标准的私人标记',concepts:['同一记号在不同技术中可以承担不同工作，表达者也能通过说明建立新约定。判断这种约定，不是只数他内心确信的强弱，而要看约定怎样接入已有计算。把一个记号当平方，涉及相应例子与纠正，而不是一个肉眼看不见的额外点缀。','意指的标准也不要求我们等到无限未来之后才判断。少量相关算例、明确说明和稳定掌握，通常足以使意思清楚。承认未来可能有错误，不等于当前全部不确定。前面数列异常让标准值得考察，却没有把标准改成一个永远无法完成的无穷试验。'],headers:['记号安排','应用表现','相关判断'],rows:[['陌生记号作平方','按平方方式取值','此处意指平方'],['同记号作两倍','按乘二方式取值','此处采用另一运算'],['偶尔算错','能够按原方法改正','未必已经改变意思']],steps:['先允许意指决定过渡的说法，让读者看见批评并不等于禁用普通句子。','再以陌生记号产生两个可区分的使用场合，说明判断意思应怎样进入实际计算。','最后回到预先决定，并以“这样”总结。论证从用途出发恢复表达，而不是把决定重新安置到不可见心灵中。'],against:['本节反对不问任何标准地诉诸原本意思，仿佛“我是这样想的”就独力说明了符号怎样规定应用。','它不否认个人能够创造记号、作出约定或报告意向。创新本身也要在可说明的技术中显出区别，而不只是获得一个心理名称。'],views:[['从符号看','新记号并不要求新数学对象。改变写法可以保留同一种运算，也可能标记另一运算，要看用途而非只看外形。'],['从规范看','一贯技术容许区别笔误与规则改变。若只把每次实际写出的结果当作意思，就会失去这种区别。'],['从解释看','标准的追问与寻找原因不同。我们可以调查脑机制，但脑机制研究不能仅凭一个意向名称替代对表达意义的说明。']],warn:[['不是心里什么都没有','原文未否认意识过程，只反对让它在无标准时承担全部规范解释。'],['不是行为次数定义意义','一贯使用不是简单统计。教学、约定、纠错及相关场合共同构成判断背景。'],['不是预先决定完全取消','作者明确保留该说法，但必须带上“这样”的回指才不会误读。']],summary:'意指能够预先规定过渡，是在一贯使用与教学提供标准的背景中说的。'});
study({id:191,short:'一下把握的图像',title:'“一下把握全部使用”，还有一种更直接的意思吗？',sub:'熟悉说法怎样被要求表达一个没有范例的事实。',tags:['理解','图像','比喻'],link:'承接190节意指的使用标准；192节给这种升级命名。',text:['“仿佛我们能够一下把握词的整个使用。”——仿佛什么，例如？——我们难道不能在某种意义上一下把握它吗？而你是在什么意义上不能？——仿佛我们能够在一种还要直接得多的意义上“一下把握”。——可是，你有这种事的范例吗？没有。只是这种表达方式向我们涌来。它是相互交错的图像所产生的结果。'],core:'第191节并不否认一下理解的正常说法，而是追问一种更强、更直接的把握究竟有何范例。混乱来自不同图像交错：一个瞬间似乎应当像一只手抓住物件那样，把全部未来使用抓在眼前；但这个超常事实并没有被说明。',more:'作者同时问“在哪种意义上能”和“在哪种意义上不能”。这使论证避开简单的肯定或否定。日常的熟练掌握可以保留；被检查的是在它之外，再要求一种更直接、却不能举例说明的完成方式。',quotes:[['词的整个使用','整个这个词容易把开放的使用活动画成一件有完整边界的物品。我们确能概括某词用法，但概括不必等于把其所有未来实例摆在意识里。作者要求说明这句话的实际意思，而非让一个全称语气自行保证内容。'],['我们难道不能在某种意义上一下把握它吗','这一反问阻止人们把前面的批评当成禁令。熟悉一个词时，我们往往无需逐条列举过去例子便立即会用它。否认一种超常把握，并不要求否认这种正常熟练。哲学澄清要能保留后者，才能准确限定前者的问题。'],['一种还要直接得多的意义','比较级在这里缺少明确比较对象。说更快，可以给出时间差；说更直接，若既不指减少步骤也不指任何可识别的能力变化，就可能只是在增强语气。作者让这种增强成为对象，而不被其庄严感带走。'],['相互交错的图像所产生的结果','图像交错能产生一种强烈的要求，却不保证要求指向真实独特对象。例如抓住物体、看清全景、立刻会做这几类图像，各有正常用途；把它们拼成瞬间包容一切未来的事实，则须另作说明。']],problem:['我们在日常生活中说“我懂了”，常不感到任何神秘。哲学反思却可能从这熟练经验走向一种要求：如果意义在使用中，全部使用就必须以某种方式同时在场。这个要求不是日常理解感本身直接提供的，而是某种意义模型额外加上的。','当无法找到全部使用同时在场的经验时，人们未必放弃要求，反而说它在更直接的意义上在场。新措辞看似超越普通经验，却也撤走了帮助我们辨认其意思的实例。作者的范例追问，就是阻止这种撤退被当作进一步解释。','本站补充：一个人看一眼地图便知道怎么走，不必真的在心里走遍每条道路。若再要求一种比看懂地图更直接、却无法说明差别的全路同时完成，就把表示与行动的图像交叠起来。这是说明比喻的补充，不是用地图定义语言理解。'],heading:'正常的立即理解与哲学升级',concepts:['“一下”在正常场合可以说明无须慢慢查找、无需重新学习或不经逐项推理。它不是总在报告一种特殊的微小时间事件。一个人具备能力，所以能立刻响应；并不因此有一个瞬间容纳能力全部可能表现的内部物件。','“范例”追问不要求凡有意义的词都必须对应一件可看的实体。它要求说明所提比较怎样使用。若说一种事情比通常理解更直接，就应能交代这种差别在哪里；不能只以没有范例证明其特殊，再以其特殊免除说明的责任。'],headers:['表达','可说明的场合','可能的误导'],rows:[['一下懂了','不需重新学习或查找','脑中瞬间存放全部未来'],['整个用法','概括相联系的使用','一件可同时抓住的东西'],['更加直接','有明确的步骤差别','纯粹增强表达语气']],steps:['先重现富有诱惑的表述，让读者承认它也许是熟悉而可用的。这样，后面的批评不会被误会成否认理解经验。','接着要求指出能与不能各在什么意义上成立。这个对照把绝对的形而上要求拆成可考察的用法，并让我们看见同一表达可以在正常场合工作。','然后追问被加强的意义有没有范例。若回答只剩一套更强措辞，就需要描述这种措辞如何由图像交错产生，而不是替它发明一个神秘事件。','末句不是把一切语言解释成幻象。只有特定图像被不加限定地叠合时，才产生此处的困难。理解图像各自的正常用处，可以使它们不再强迫我们接受同一个过度结论。'],against:['本节反对用一个没有明确定义的更直接意义，替代原先未被说明的理解机制。强烈的表达冲动不能充当对象存在的证明。','它不反对迅速理解、整体概括或使用比喻。这些活动完全可以有清楚位置；问题是是否要求它们共同担保一种超出所有实例的特殊事实。'],views:[['从阅读看','读者要保留问答次序。若只摘出“没有范例”，就容易误以为作者否认一切立即理解；若只摘出可以一下把握，又会错过对增强解释的批评。'],['从认知描写看','熟练者不需重新查找，与他在意识中完成无限预演，是不同描述。前者可以普通而重要，不能因为普通就被视为不足以说明理解。'],['从比喻看','一个比喻本可突出联系，交叠后却可能迫使我们要求不存在的共同对象。拆开比喻的工作，是恢复比较的边界，并非剥夺语言的表达力。']],warn:[['不是凡无图像就无意义','范例问题针对一个被声称存在的特殊把握，不是给所有词设置图像对应标准。'],['不是“一下懂了”必须删除','作者明确允许正常意义。需要澄清的，是它被赋予的更强哲学负担。'],['不是描述一个新发现的脑机制','图像交错是对哲学表达的诊断，不能直接变成未经实验验证的神经科学结论。']],summary:'立即掌握可以有正常用途，但加强成更直接的超常事实时，必须说明比较与范例。'});
study({id:192,short:'哲学的最高级',title:'越说越强，是否真的说明了更多？',sub:'给没有范例却不断增强的表达一个诊断名称。',tags:['表达','最高级','澄清'],link:'总结191节加强把握的冲动；193节转向机器图像。',text:['你没有那种超常事实的范例，却被诱惑着使用一种过度表达。（可以把这叫作一种哲学的最高级。）'],core:'第192节将一种哲学动作称为最高级：无法指出所声称的特殊事实，却不断加强措辞，使它显得比通常事实更直接、更根本、更确定。作者要我们检查语言的增强是否真正增加了内容，而不是把增强本身当成思想已经深入的标志。',more:'这是承接前节的一句诊断，不是禁止所有最高级词语。比较可以明确，最严格、最快也可以有标准。本节针对的是先排除正常范例，再用超强表达制造似乎还有一件更大事实等待发现的情况。',quotes:[['你没有','第二人称延续前节的对话。作者不是对全人类知识作一个绝对总判决，而是对眼前这个主张提出要求：你能否指出自己正在要求什么。这个限定应当保留，否则一句局部诊断又会被扩成作者反对一切理论的口号。'],['超常事实的范例','超常事实不是一个新科学术语。它指前节设想的，比正常一下把握还更直接的特殊成就。原先没有说明的事情，不能仅因被冠以超常性质就自动免除举例和比较的责任。'],['被诱惑着使用一种过度表达','语句可以带来确定感、终极感和发现感，但这些感受不等于说明已经完成。作者关注的是为什么我们想这样说，以及这种说法如何遮住原本简单的使用联系。诊断其诱惑，不必否认说话者的认真。'],['一种哲学的最高级','最高级在这里把普通语言现象概括成一种哲学倾向：不是更好完成某项已有任务，而是把任务无限提高，直到无人知道怎样完成。给它命名，是为了使这一动作可以被辨认，不是再建立一种关于所有哲学的本质定义。']],problem:['在日常比较中，提高程度常有明确尺度：更短的时间、更少的步骤、更小的误差。哲学最高级却可能不断去掉这些尺度，仍保留更根本、更直接的语气。于是论证看起来在前进，实际上失去了辨认差异的办法。','前面的数列讨论说明了这种诱惑的来路。我们不满足于训练、解释与正常应用，因为它们似乎仍可能异常；因此要求意向以独特方式预先完成一切。当独特方式无法描述时，又说这种完成比通常完成还更直接。表达增强替代了原本应提供的说明。','本站补充：若人把普通的承诺看成不够确定，要求一种比一切可能兑现都更真实的承诺，却拒绝说明它如何区分于普通承诺，我们便会追问这种更真实在做什么。这个例子只比较表达结构，不用本节否认伦理承诺的实际分量。'],heading:'程度的提高与用途的消失',concepts:['一项比较要有工作，需要能说明什么变化算提高。这个标准未必总是数字，也可以来自具体实践。但若所有可能用来说明的变化都被排除，只剩一种必定还有更深东西的确信，最高级就可能不再表达比较，而在制造一个空位。','过度表达有时恰以无法举例证明自身重要：它说普通例子都不够，所以所谈必定更高。这倒置了说明的责任。缺少范例可以促使我们继续澄清，也可以表明我们尚未说清；它不能单独证明一个更高对象已经存在。'],headers:['比较方式','有用的检查','可能出现的困难'],rows:[['更快理解','用时或学习步骤有差别','速度被改写成无限同时在场'],['更确定回答','判断条件得到说明','要求取消一切实践背景'],['更直接把握','说明减少什么中介','只加强语气而不增内容']],steps:['第一步回指前节：所谓超常事实，正是比通常理解更直接的那种把握。因而本句不能完全脱离前文当作一般训诫。','第二步将注意力从想象的事实转向正在说出的表达。我们可以先考察增强语气的动作，而不用立刻承认它指向一个待发现的超常过程。','第三步给这种动作取一个便于识别的名称。名称的价值在于帮助后续比较，例如机器的所有运动是否也被想成比实际运动更严格地预存。它不是让读者记住术语就算结束。','在实际精读中，还应反问自己的解释有没有重演同一错误。若把最高级说成一项包办全部哲学问题的总原则，或宣称作者已获得绝对透明的语言视角，就会再次以更强措辞代替具体比较。这个自我检查是本站对方法的展开，不是本节另列的新规则。'],against:['本节反对把说明中的空缺包装成事物的超常性质。无法说清“更直接”不应被当成已经触及思想最高境界的证据。','它不反对严格性、精确化或真正的概念创新。若新比较能展示差别和用途，它就不能仅因语气强或概念抽象而被本句预先否定。'],views:[['从修辞看','最高级能增强读者期待。哲学澄清要让这种修辞作用与论证职责分开，不能只因一个词令人震动，就认为它已排除其他解释。'],['从方法看','有时前进不是增加一层新理论，而是撤回一个无根据的要求。说清不再要求什么，能让普通的学习、应用和纠错重新显出其作用。'],['从阅读伦理看','认真对待作者，不等于追随每个庄严词语。读者可以尊重困惑的力量，同时要求概念的区别得到展示；这也避免轻率把所有难句都斥为胡说。']],warn:[['不是禁用最高级','日常与技术比较可以有明确标准。被批评的是无范例而继续增强的哲学要求。'],['不是所有深刻思想都空洞','本句只有放回前节才能识别靶子。不能以它代替对别的思想逐项分析。'],['不是以简单为唯一价值','说明可以复杂。作者追问的是复杂表达承担什么工作，不是字越少思想越真。']],summary:'当增强措辞不再说明任何可辨认的差别，哲学的最高级便可能代替了真正的解释。'});
study({id:193,short:'机器作为符号',title:'机器还没转动，所有运动已经藏在里面了吗？',sub:'区分预测实体机器与使用机器图来表示运动。',tags:['机器','符号','预定'],link:'将191—192节的过度确定转到机器；194节检查可能性的实体图像。',text:['机器作为其运作方式的符号：机器——我首先也许会说——仿佛已经把自己的运作方式包含在内。这是什么意思？认识机器之后，其余一切，也就是它将做出的运动，仿佛都已完全确定。','我们说得像这些零件只能这样运动，不能做别的。怎么回事，我们忘了它们可能弯曲、折断、熔化等等吗？是的，在许多情况下我们根本不想到这些。我们把机器或机器的图像，当作某种运作方式的符号。例如，我们把这幅图传给别人，假定他能从中推出零件运动的现象。（就像我们告诉别人一个数，说它是1、4、9、16……这个数列的第二十五项。）','“机器仿佛已包含自己的运作方式”意味着：我们倾向于把机器未来运动的确定性，比作已经放在抽屉中、随后被我们取出的物品。可是，预测机器实际行为时，我们并不这样说；我们通常不会忘记零件变形等可能性。只有当我们惊讶：机器既然也能完全不同地运动，我们怎么还能把它当作某种运动方式的符号时，才会如此。','我们可以说，机器或它的图像，是一系列图像的起点；我们已经学会从这幅图推出后续图像。','可是，当我们想到机器也可能以别种方式运动时，便仿佛在作为符号的机器里，其运动方式必须比在实际机器里还要确定地被包含着。仅仅说这些是按经验预先规定的运动，还不够；它们仿佛必须在一种神秘意义上已经在场。而确实，机器符号的运动，是以不同于某台实际机器运动的方式被预先规定的。'],core:'第193节区分机器的两个角色：一台实际装置可以出故障，一幅机器图却可以在既定技术中表示确定的运动序列。把两种预定混合，便会觉得符号内部一定已经神秘地存放所有未来运动。作者保留区别，拒绝以隐藏存货解释它。',more:'原文最后明确说，两种预定方式确实不同。澄清不是宣称符号与实体机器毫无差别，而是说明差别怎样来自表示用途与实际预测的任务，不必再加上一层比物理刚性更刚的神秘存在。',quotes:[['机器作为其运作方式的符号','开头限定了本节的观察角度。我们有时拿机器图说明怎样运动，而非调查眼前装置是否会断裂。同一对象可以进入不同活动；若略掉这个角色差异，便容易要求一种既能表示规则又保证实际无事故的超常机器。'],['它们可能弯曲、折断、熔化','这些可能性属于实际机器预测的重要条件。作为运动表示时不考虑它们，可以是合理的抽象；但抽象不能被误当作发现了一台绝对不会变形的实体。作者不是因有故障便否认设计推导，而是要求分清推导与预测。'],['已经放在抽屉中','抽屉比喻把未来运动物化成预存对象。它使“已经确定”看起来只能由“已经存在”解释。可一个图在技术中可推出后续图，并不意味着后续运动以缩小形态藏在图里。去除比喻，不会取消正常推导。'],['我们已经学会从这幅图推出后续图像','这一句提供一个实际联系：会读机器图的人能够按学过的方式继续。它并非说学习过程足以保证真实装置永不故障，而是说明表示的确定性可以怎样工作。规则图与物理机器需要不同说明，不能用同一个隐藏运动对象代替。']],problem:['看到一张熟悉机构图，我们会说这里的运动已经规定好了。这在工程或教学中可以有清楚意义。问题在于把规定好了解释成未来运动已经存在，再把这种存在说成比现实运动更纯粹、更严格，于是制造一个无须说明的特殊世界。','机器可能坏掉这一事实，本来要求我们区别设计与实际行为。然而哲学惊讶会把区别转换成另一要求：既然真实机器不能保证全部，作为符号的机器就必须以更绝对方式保证全部。这样，实践中的角色差异被改写为两个不同等级的存在。','本站补充：装配图可以规定螺钉的正常位置，而工厂中的螺钉可能松脱。不能因为松脱可能，就说图纸毫无规定作用；也不能为了保住图纸作用，设想图纸里有一枚绝不松脱的神秘螺钉。原文讨论运动，这个补充仅比较规定与实际失效的区别。'],heading:'表示中的必然与经验中的预测',concepts:['把机器图当符号，是在一种学会的表示技术中工作。零件位置与后续运动怎样对应，可以通过示范、图解和推导说明。图纸的角色不是一台尺寸更小的实际机器，它可以规定或展示运动，而不以实际发生那次运动为条件。','预测实际机器行为则要考虑材料、负载、温度和磨损等条件。这里可以有可靠经验与精细计算，但其说明方式不能直接当作规则图的语法。作者要求避免将两种任务混合，既不取消工程知识，也不把抽象提升成超越一切实践的物件。'],headers:['机器的角色','所作工作','相关异常'],rows:[['实际装置','预测实际运动','断裂、变形、熔化'],['机构表示','按技术推出后续图','读图错误或表示不明'],['神秘抽屉图景','把确定画成预存','尚未说明所谓预存']],steps:['先承认机器似乎包含运作方式的普通印象，然后追问这个印象是在什么任务中形成。','再把实际预测与表示用途并列。忽略变形可能，在一种任务里是简化，在另一种任务里却可能造成错误。','随后以图像序列给出替代描述：我们学会从图继续。这个描述保留确定性，却不把它画成装满未来的容器。','最后保留两种预定的区别，并指出神秘要求正由误解这个区别产生。解释的目标不是将不同压成相同，而是让不同不再需要隐藏实体来维系。'],against:['本节反对把运动的确定性当成未来运动已经以特殊方式实际存在。它也反对因实际机器会坏，就要求符号必须是更坚硬的超实体。','它不反对工程简化、机构模型与可靠预测。模型可以有明确用途；需要避免的是遗忘用途，再把模型性质当作对象无条件的全部性质。'],views:[['从建模看','抽象掉故障是一种用途选择。它能帮助推导正常运动，但不能由此断言真实材料没有变形可能。'],['从时间看','未来已被规定不等于未来已发生。把规范关系和事件先后混合，会要求一个没有普通实例的特殊现在。'],['从语言看','包含、已有、取出等词把不同工作放进容器图像。作者让比喻变得可见，是为了使普通表达重新获得适用边界。']],warn:[['不是实际机器不可预测','预测可以准确，原文只区别它与作为符号时的预定方式。'],['不是符号脱离实践独立运行','图像序列之所以可推出，涉及已经学会的技术。图的线条不凭自身完成全部读法。'],['不是二者预定毫无区别','结尾肯定区别存在。被撤回的是用神秘预存解释区别，而不是区别本身。']],summary:'机器图可以规定运动，实际机器可以出故障；二者的区别不需要未来运动神秘预存来解释。'});
study({id:194,short:'运动可能性的影子',title:'可能性是一场尚未发生的微小运动吗？',sub:'追踪“拥有可能性”的措辞如何制造影子实体。',tags:['可能性','语法','机器'],link:'展开193节的机器图景；195节恢复某种意义上在场的正常说法。',text:['人在什么时候会想，机器以某种神秘方式包含了它的可能运动？——在做哲学的时候。是什么诱使我们这样想？是我们谈论机器的方式。例如，我们说机器拥有这些运动可能性，谈论一台只能如此运动的理想刚性机器。运动的可能性是什么？它不是运动本身，但似乎也不只是运动的物理条件，例如轴承与轴销之间有空隙，轴销没有卡得太紧。因为，这虽是运动的经验条件，却也可以设想另一种情况。运动可能性仿佛更像运动本身的影子。但你认识这样的影子吗？我说的影子不是某幅运动图像；因为那幅图未必就是这一个运动的图像。可是，这个运动的可能性，必须恰是这个运动的可能性。（看看语言的浪涛在这里涨得多高！）','一旦我们问：谈机器时，我们怎样使用“运动可能性”这个词，浪涛就平静了。那么，古怪观念从哪里来？我比如用运动图像向你展示运动可能性，于是：“可能性是类似现实的东西。”我们说：“它还没有运动，但已有运动的可能性”，于是：“可能性是某种很接近现实的东西。”我们也许怀疑某个物理条件是否使这个运动成为可能，却从不讨论这到底是这个运动还是那个运动的可能性，于是：“运动可能性与运动本身具有独特关系，比图像与对象的关系还紧密”；因为可以怀疑一幅图究竟是这个还是那个对象的图像。我们说：“经验会表明，这是否给轴销提供这种运动可能性”，却不说：“经验会表明，这是否是这个运动的可能性”，于是：“这个可能性恰是这个运动的可能性，并非经验事实。”','我们注意到自己谈这些事的表达方式，却不理解它，反而误解它。做哲学时，我们像那些听到文明人表达、却误解表达，并从中推出最古怪结论的原始人。'],core:'第194节分析一种从语法到实体的误推：因为我们说机器拥有可能性，又把可能性与特定运动相连，就把可能性想成运动的影子，一种比图像更贴近现实的东西。作者要求回到表达的使用，而不是寻找这个影子到底放在哪里。',more:'本节长段中的几个“于是”都属于被检查的推论，不是作者给出的可能性理论。结尾的文化比喻是原书措辞；它用于描述哲学家误读自己熟悉表达的处境，不能借此推出对真实族群能力的等级判断。',quotes:[['运动本身的影子','影子图景试图满足两个要求：可能性还不是运动，却要像运动；它又必须专属于该运动。图景因此被不断加强。作者问是否认识这样的影子，是在检查这些要求有没有明确用途，不是邀请寻找更精细的不可见物质。'],['我们怎样使用“运动可能性”这个词','回到使用不是逃开难题。难题正由表达被误读成对象报告而起，检查表达怎样工作才能说明误推发生在哪里。可说明的间隙、机构和表示方式，不必共同指向一个像运动的影子。'],['比图像与对象的关系还紧密','更紧密的结论把概念上的联系画成两件东西之间的特殊胶合。我们不能把这个运动的可能性当成另一个运动的可能性，是表达中的区别；它不证明存在两件独立物体，并由一种超强关系相连。'],['并非经验事实','这里的否定不等于宣布发现了更深的先验实体。某种表达不是用于经验检验，可以说明其语法工作，而不必由此推出另一类神秘事实。作者要防止从经验与非经验的差异，跳到两种世界的图景。']],problem:['说机器拥有运动可能性，语法上像说抽屉拥有物品。人便容易追问那个被拥有的东西是什么。若回答物理条件，似乎不足；若回答图像，又嫌它可有不同解释。于是形成一种既不是现实又必须精确贴合现实的影子要求。','原文逐项重现误推：展示运动图像被说成证明可能性像现实；已有可能被说成证明可能性接近现实；概念联系不能被当作同种经验问题，又被说成证明一种比图像更紧密的特殊关系。这些推论共同把用法差异投射为隐藏对象的属性。','本站补充：说门可以打开，可能涉及锁未关、铰链完好或制度许可；我们不会因此要求门里已有一扇半现实的打开过程。这个补充展示拥有可能性不必是持有某种物件，不能把几种可能性用法反过来归并成同一个本质定义。'],heading:'物理条件、图像与概念联系',concepts:['物理条件需要经验检查：空隙是否足够、材料是否卡住，都可通过测量和试验确定。一个关于“这个运动”的表达怎样被区分，则不总是同一种调查。承认两种问题不同，不意味后者必须涉及超经验物件；它也可以只是说明我们怎样使用描述。','图像可以展示可能运动，却不因此就是可能性本身。我们借地图说明路线，不必把路线的可行性认作地图上的一条墨线。相似的提醒适用于机器图。这里的比较帮助拆开表示与所表示的关系，而非宣称一切表示都不可靠。'],headers:['材料','实际工作','误推'],rows:[['轴承间隙','使运动在物理上可行','它不够神秘所以不算条件'],['运动图','展示一种机构活动','可能性必是一幅准现实图'],['这个运动的可能性','在表达中限定对象','存在超强胶合的影子实体']],steps:['首先提出神秘包含的场合，并把诱因定位到我们自己的表达。机器不是突然显出怪异现象，而是被哲学措辞重新安排。','接着列出影子对象须满足的要求，使读者看到这种候选如何被逐步制造。每次拒绝普通说明，都把对象的要求抬得更高。','然后一项项追溯这些要求的语言来源。对原句能够正常使用的承认，与对原句哲学误解的纠正同时进行。','最后将问题归回误读表达。任务不是禁止说可能，而是让不同的可能性说法重新进入各自可说明的场合。'],against:['它反对从语法上的拥有直接推出拥有一件影子对象，也反对将非经验的概念联系理解成更强的物理或精神联结。','它不否认可能性有清楚意义，不反对机械设计，更不把关于自然条件的经验调查宣布无用。'],views:[['从模态表达看','可能不总是给一个未发生事件贴上较低存在程度。它可以在各类活动中说明条件、许可或结构关系。'],['从图像看','图像帮我们展示，却需要读法。若因读法可变就再找一张更严格图像，可能重启前面已经显露的同类困难。'],['从方法看','逐句追溯误推，比只说一切是语言游戏更有解释力。每一步都要指出什么表达被怎样错读，不能用口号替代。']],warn:[['不是作者接受影子理论','本节主体正在演示该理论的诱惑。读者必须识别“于是”引出的被批评推论。'],['不是无法经验检验便无意义','概念与规则有自己的工作，不必都成为经验假说，也不必因此被取消。'],['不是族群等级理论','结尾比喻属于原书时代措辞，其目标是哲学家的自我误读，不能被读成经验人类学判断。']],summary:'可能性与运动的语法联系，不需要被改画为一件与现实超强相连的影子物。'});
study({id:195,short:'奇怪来自错放语境',title:'“未来使用已经在场”，哪里说错了？',sub:'作者保留正常说法，撤回附加的神秘性。',tags:['在场','语言游戏','误解'],link:'承接194节可能性实体化；196节概括误解词语如何变成奇异过程。',text:['“可是，我并不是说，我现在理解时所做的事，在因果和经验意义上决定未来使用；而是说，在一种奇怪的方式中，这个使用本身在某种意义上已经在场。”——但它的确在“某种意义上”在场！严格说，你的话错的只是“以奇怪方式”这个表达。其余是对的；只有当我们给这句话想象另一个语言游戏，而不是实际使用它的那个游戏时，它才显得奇怪。（有人告诉我，他小时候惊讶于裁缝“能缝一件衣服”——他以为，这意味着纯粹靠缝、把一根线缝到另一根线上，就能制造出一件衣服。）'],core:'第195节保留在某种意义上未来使用已在场的说法，问题在于把它想成一种奇怪过程。表达在其实际语言游戏中可以正常工作，移入另一幅未经说明的图景，才像是在报告神秘事实。裁缝的例子让这种误放语境具体可见。',more:'这不是作者从否定忽然转向神秘主义。承认一句话有正常用途，与承认它的超常解释是两回事。原文指出错在奇怪方式，正是把日常表达与误解表达分开，而不是用另一套形而上学解释替换原有解释。',quotes:[['在因果和经验意义上决定未来使用','异议者已经看出单纯因果预测不足以说明规则要求。他不满足于说理解造成后来行为，转而要求使用本身现在以特殊方式出现。这个转移值得认真处理，但拒绝因果理论并不会自动证明另一种超常在场。'],['它的确在“某种意义上”在场','作者没有以一概否认回答异议。我们可以说安排已做好、规则已规定、意向已明确。这些正常说法能说明预先性，却不要求未来事实缩成一件当前物体。这里的某种意义必须在用法中说明，不能任意容纳一切主张。'],['错的只是“以奇怪方式”这个表达','这一限定把批评精准地放在附加的神秘解释上。不能将它读成凡自己不理解就算奇怪，也不能把其余是对的读成作者批准所有原有预设。问题是究竟在什么语言活动中，那些措辞能够清楚地工作。'],['把一根线缝到另一根线上','孩子熟悉缝这一动作，却把制造衣服理解为只把线彼此连接，漏掉布料和裁制等活动背景。原文借此说明，一个词字面上看似熟悉，仍可能被放入错误工作图景。误解不证明缝纫真的包含神奇创造过程。']],problem:['前面几节拆开因果预定与规范联系后，读者可能仍坚持一种非因果的奇异在场。若直接说一切都不在场，又会否认正常语言中已有安排、已懂用法等表达。本节选择更细的工作：保留可用说法，并说明它怎样变怪。','语句并非随身带着唯一不变的形而上解释。把它从学会规则、发出邀请、确定计划的场合中抽出，放进当前意识必须容纳未来的模型，就会制造一种正常使用本身没有要求的事实。奇怪感由这个移置产生，不是由新观察提供。','本站补充：说乐谱里已有旋律，可以说明熟练演奏者能据谱演奏；若由此追问纸上怎样塞入未来的实际声波，就把表示用法当成物理容纳。这个补充比较与裁缝误解相似，不能据此把乐谱、规则、意向的一切差别都抹平。'],heading:'正常预先性与神秘在场',concepts:['正常说法能够省略许多熟悉背景。说裁缝缝衣服，不必每次附上布料、剪裁、针线和训练的清单。省略之所以有效，是这些活动已经在实践中有位置。哲学误读却把省略当不存在，再要求单个动词完成全部工作。','语言游戏不是为难句任意找一个免责语境。要指出原句如何实际使用，谁在何种活动中说它，有哪些接续和纠正。若没有这层展示，只说它在某种游戏里必定正确，同样会用一个标签代替解释。本节用裁缝例子正提供这种具体对照。'],headers:['表达','正常背景','错放后的期待'],rows:[['会缝一件衣服','裁制与缝纫技艺','仅靠线与线造出整件衣服'],['使用已被确定','已掌握的规则与安排','未来事件现在缩形存在'],['某种意义上在场','能说明的表示或规定','无需说明的奇异实体']],steps:['先让异议区分因果与非因果，保留其真正关心的规范问题。','再承认某种意义上在场的日常可能，避免将反神秘解释变成一概否认。','随后把奇怪感定位到语言游戏的移置。我们需要解释移置怎样发生，而不是再描述一种神秘在场。','最后以孩子对裁缝的误会作对照。例子让熟悉词的陌生解释可以被看见，也为下一节词语被当成过程的概括提供材料。'],against:['它反对在排除因果说明后，立即把剩下的联系叫作神秘过程。非因果并非神秘的同义词，也不意味着说明可以停止。','它不反对日常说将来已经安排好，也不要求说话者每次展开全部背景。普通简略与哲学误解必须分开。'],views:[['从学习看','孩子的误解并非仅是不认识某个名词，而是对一项活动怎样组成缺少了解。释词有时需要展示实践，而不只替换同义词。'],['从语境看','同一句话可以因进入不同工作图景而显得怪异。指出其原有场合，是检验的一部分，不能只凭一句话的表面形式下判决。'],['从方法看','维特根斯坦常以保留表达、撤回误解推进。这比简单禁说某词更精细，也要求解释者明确哪些内容被保留，哪些附加要求被撤回。']],warn:[['不是一切意义都随意','语言游戏有实际做法和标准，不是给任意句子随便编一个理由。'],['不是作者承认神秘在场','他明确指出奇怪方式是错误所在。去掉限定就会扭转论证。'],['不是因果调查无价值','本节只是说当前困扰不能靠把非因果联系神秘化来解决，没有禁止研究理解的心理原因。']],summary:'一句话可以正常地表达预先规定；奇异在场来自把它放进了不相干的工作图景。'});
study({id:196,short:'把词误读成过程',title:'我们不懂一种说法，为什么会以为发现了神秘过程？',sub:'从误解的表达回到它原本承担的工作。',tags:['过程','误解','语法'],link:'概括195节裁缝例子；197节以想下棋检查意向与规则的联系。',text:['词语未被理解的使用，被解释为一种奇怪过程的表达。（就像把时间想成一种奇怪的介质，把心灵想成一种奇怪的存在。）'],core:'第196节概括一种误推：我们没有弄清词语怎样使用，却把这份不理解解释成它必在指一种奇怪过程。陌生感原本属于我们的理解状况，随后却被移成对象自身的神秘性质。时间与心灵的括号例子，提示这种转换可在许多哲学讨论中反复发生。',more:'作者没有由此否认真实的时间研究、心理体验或未知过程。他要求先辨认问题来自什么：是已有清楚问题却尚未找到经验答案，还是表达的工作尚未弄清，就预先给它安置一个奇异对象。二者不能只因都令人困惑而合并。',quotes:[['词语未被理解的使用','起点是用法未明，不是观察到一种新奇现象。我们也许能重复词句、觉得语气熟悉，却没有说清它在活动中的位置。这种不足需要通过比较和展示补上，不能仅靠声称词背后必有某件东西来跳过。'],['被解释为','这三个字标出一次转换。我们将自己的困惑重新叙述成关于世界的判断：不是我还没弄清说法，而是对象必定十分特殊。转换可能有吸引力，但需要根据，不能从不理解本身直接推出对象性质。'],['一种奇怪过程的表达','表达被看成报告过程，随后问题便转成该过程如何发生。这样追问可能永远找不到满足，因为原来的词未必是在报告同一类型的事件。作者要求检查这个报告模型，而非给奇怪过程再取一个科学化名称。'],['把时间想成一种奇怪的介质','介质图像把时间放到承载事物的容器位置，仿佛它是一种比水或空气更难看见的材料。括号并没有逐一分析所有时间观，而是让读者看见类似的对象化手法。心灵例子也应作同样有限的理解。']],problem:['哲学追问常从一个句子开始：意义已经在场、意向指向未来、时间流逝。若没有先看这些表达怎样工作，就把它们全部读成事件报告，我们会要求寻找一项与句子对应的隐藏过程。找不到时，过程又被说成越发神秘。','这种解释使困惑自我加强。普通经验不能满足它，因为它从一开始就将所寻者设为异于普通经验；解释越失败，似乎越证明对象超常。作者让我们倒过来看：失败可能提示报告模型不适用，而不必提示对象具有一种更高等级的存在。','本站补充：人说“我抓住了你的意思”，若问他抓住的东西有多重，就把理解表达当成拿取物体的报告。接着说那是一种没有重量的特殊抓取，并未解决误会。这个补充只帮助展示语法误读，不证明所有有关理解的心理过程都不存在。'],heading:'无知的原因与对象的性质',concepts:['我们不知道某事，可能因为材料不足，也可能因为提问尚未形成清楚任务。前者可要求调查，后者可要求澄清。第196节聚焦后一类，却没有把一切未知都归入后一类。若不保留这一区分，就会把作者的方法误写成对经验研究的全面拒绝。','过程词语有正常标准：何时开始、持续多久、如何结束、与其他过程怎样区分。若一种哲学描述不断调用过程图像，又拒绝所有相关问题，便值得检查它是否仍在以同样方式使用过程一词。问这些，不等于把全部心灵现象都强行物理化。'],headers:['困惑','未经检查的转换','可继续的检查'],rows:[['不懂预先在场','必有特殊心理过程','在场在此做什么工作'],['谈时间','时间必是隐形介质','比较时间表达的实际用法'],['谈心灵','心灵必是特殊物体','区分体验、能力与解释模型']],steps:['首先分清起点：未理解的是词的使用。这个定位使读者不必先接受一个被报告的神秘对象。','然后看转换：未明用法被重新当作表达奇怪过程。论证真正需要检查的是这个从用法到对象的跳跃。','最后借两个括号例子扩展比较。它们只是提示同类误读的形式，没有一次完成时间哲学与心灵哲学的全部工作。','回到具体困惑时，应先找表达的正常场合，再问当下是否发生移置。如果仍有明确经验问题，就进行相应调查；如果移置被解除，原先那个必须找出的过程可能不再是一个需要执行的任务。'],against:['它反对从说法难懂直接推到对象必定神秘，也反对以新的术语掩盖原先尚未说明的报告图像。','它不否认复杂经验、科学未知和人的精神生活。澄清用法的任务，不能被误用为宣布这些研究都只是误会。'],views:[['从问题诊断看','问题尚未清楚与答案尚未知，虽都可说不知道，却需要不同工作。分清二者是继续思考的条件，不是退缩。'],['从表达看','语言能用动作图像说明非动作活动。误解发生在把这种借用未经检查地当成同一种过程结构。'],['从自我检查看','解释者也可能用奇怪语法过程之类词再次制造隐藏机制。应说明实际的误读步骤，而不只给困惑贴标签。']],warn:[['不是所有过程都是假象','原文只诊断一种由未明用法构成的推误。真实过程仍可被观察、描述和解释。'],['不是语言之外什么都没有','从某种实体图像不合适，不能推出世界只由词语组成。作者没有在此提出这种本体论。'],['不是括号已经解决所有问题','时间与心灵是比较线索。要处理具体争论，仍须逐项展示相关表达怎样使用。']],summary:'用法未明不等于发现神秘过程；先要检查从困惑到对象性质的那次转换。'});
study({id:197,short:'意向怎样连到规则',title:'我还没下棋，怎么已经知道自己想玩什么？',sub:'规则目录、教学和日常实践，而非意识里的超刚性纽带。',tags:['意向','规则','实践'],link:'承接196节奇异过程的诊断；198节说明解释本身不能独力奠基。',text:['“仿佛我们能一下把握词的整个使用。”——我们确实说自己这样做，也就是说，我们有时就用这些话描述自己的所作所为。但发生的事情并无什么惊人或奇怪之处。只有当我们被引向这样想时，它才变怪：未来的发展必须以某种方式已经在理解动作里在场，却又不在场。因为我们说，毫无疑问我们理解这个词；另一方面，它的意义在于它的使用。毫无疑问，我现在想下国际象棋；可是国际象棋之所以是这个游戏，是由它的全部规则等规定的。那么，在实际下过之前，我还不知道自己想玩什么吗？或者，全部规则都包含在我的意向动作中吗？难道是经验告诉我，这种意向动作通常接着这种下法？因此，我仍不能确定自己原本打算做什么吗？如果这是无意义的，那么意图动作与所意图之物之间，又存在什么超刚性的联系？——“我们下一盘国际象棋吧！”这句话的意义，与游戏全部规则的联系，是在哪里建立的？——在游戏规则目录中，在国际象棋教学中，在日常下棋的实践中。'],core:'第197节既保留我们知道自己想下棋的正常确信，也拒绝把确信解释为所有规则已缩在一个意识瞬间里。意向与游戏规则的联系，不必是概率上的因果预测，也不必是超刚性的心灵纽带；它已在规则表述、教学与实际下棋中建立。',more:'开头允许正常地说一下把握，结尾提供联系的实际位置。中间连串疑问主要在演示错误选择如何形成：要么未来全部在场，要么只能事后猜测意向。作者不接受这个二选一，也不以意向毫无内容来摆脱它。',quotes:[['我们有时就用这些话描述自己的所作所为','日常表达可以正常使用，不能只因它听起来像整体把握就立即判成错话。要检查的是后来附加的模型：这些话是否被当成报告一个将无限使用压缩入瞬间的过程。保留表达与撤回模型可以同时进行。'],['我现在想下国际象棋','这是一个普通而有内容的意向，不必等下完之后才知道其对象。我们也不需要回忆某一瞬间全部棋规的心理清单。原文选择熟悉游戏，正为了让这两点同时显而易见，从而迫使错误理论让路。'],['超刚性的联系','当因果预测显得太弱，哲学就可能要求比一切经验都更强的连接。这个要求重演机器符号比真实机器更刚的图像。作者并非寻找一种更好的胶水，而是检查是否误把规范关联画成两件物体之间的连接。'],['在日常下棋的实践中','结尾不是含糊诉诸生活。它与规则目录、教学并列，列出可以继续展示的具体活动：邀请、走子、纠错、学习和判断一局是否在按规则进行。联系在这些活动中工作，而非藏在一个无法说明的微小意向里。']],problem:['如果意义在使用，理解却在现在发生，人似乎被迫选择：要么全部使用已经在现在出现，要么现在根本不能理解。下棋意向把这种两难变得鲜明：我没有走完全部可能棋局，却仍知道自己打算玩什么。','另一项诱惑是把意向当成未来行为的原因，凭以往经验才推测之后会做什么。若这样，我对自己的意向似乎只能有概率信心。作者没有用内在绝对纽带来替换概率联系，而是提示意向本来属于已有游戏与教学的语法背景。','本站补充：说“我准备弹这首曲子”，不必意识里响过全部音符，也不只是在预测身体稍后会出现某些动作。音乐学习和演奏活动使这句话有内容。这个例子只比较意向与技术的关系，不将国际象棋的规则结构等同于全部艺术活动。'],heading:'意向的内容与实践中的联系',concepts:['理解某个游戏，并不要求在每次发出邀请时同时背出全部规则。规则作为一种持续可用的技术，能在当前意向中发挥作用。持续掌握与瞬时心理内容需要区分，正如前面知道字母表不等于整夜背诵字母表。','“联系在哪里建立”不是在问身体某个位置发生了什么物理事件。原文用目录、教学、实践回答，显示它要说明表达如何进入游戏。若坚持只有一种心理或物理纽带才算真正联系，就已经把答案限定为作者正在批评的模型。'],headers:['候选解释','引出的困难','可保留的事实'],rows:[['全部规则缩在意识瞬间','缺少明确范例','当下可以知道想玩什么'],['靠经验预测后来动作','把意向变成行为猜测','意向与行动确会相关'],['教学与规则实践','需要展示具体做法','游戏内容可在当前被掌握']],steps:['先承认整体把握说有正常用途，使讨论不会与普通理解经验对立。','再通过下棋意向列出两难：必须先下过，或者必须脑中已有全部规则。这两项要求都来自一幅尚未澄清的内容模型。','随后指出因果预测也不足以替代意向的正常语法，但不因此跳向超刚性内在纽带。','最后将联系放回规则目录、教学和实践。这个回答不是一个新的隐藏机制，而是邀请我们展示原先被抽掉的背景。'],against:['本节反对在意向与实践之间要求一个既非经验又非可说明技术的超强联结。那只是将问题搬进一个更神秘的空间。','它也反对把第一人称意向仅当作对未来行为的概率预测。原文并没有为避免内在论而取消人通常知道自己想做什么。'],views:[['从心理看','意识体验可以伴随意向，但体验本身没有必要容纳全部规则。我们需要分别描述体验发生与意向内容如何被说明。'],['从制度看','规则目录、教学和对局不是装饰性外壳。它们帮助形成这个游戏及其相关表达的意义，使邀请与后续行动相接。'],['从方法看','寻找联系不总意味着寻找额外对象。有时把被省去的活动重新并列，便能说明为何原先看似缺口的位置并不需要神秘填充。']],warn:[['不是下完才知道想玩什么','这正是原文呈现并拒绝的困境之一。熟悉游戏者可以现在就有清楚意向。'],['不是规则只是一份文字','目录只是三项中的一项，还包括教学与实践。规则文字自身仍需被理解和使用。'],['不是实践替代全部思考','人仍可以讨论、解释和修改规则。原文只拒绝这些活动之外另有一条超刚性纽带的要求。']],summary:'意向与棋规的联系在教学、规则表述和下棋实践中工作，无需把全部未来塞进当前意识。'});
study({id:198,short:'解释不能单独奠基',title:'再加一个解释，能最终保证规则的用法吗？',sub:'指路牌的作用既涉及训练，也涉及持续的习俗。',tags:['规则','解释','习俗'],link:'接197节的实践联系；199节进一步说明遵从规则的可重复背景。',text:['“可是，一条规则怎样能教我在这个位置该做什么？无论我做什么，总可通过某种解释使它与规则一致。”——不，不应这样说，而应这样说：任何解释，都连同被解释的东西一起悬在空中；它不能给后者提供支撑。只有解释，不能决定意义。','“所以，无论我做什么，都与规则一致吗？”——让我这样问：规则的表达，比如指路牌，与我的行动有什么关系？这里有什么联系？——例如，是这样：我受过训练，要以某种方式回应这个记号，所以现在便这样回应。','可是，你这样只指出了因果联系，只解释了我们如今为何会依指路牌走，并没有解释这种依记号而行究竟在于什么。——不是；我还暗示了：一个人只有在存在持续使用、存在一种习俗的背景中，才是在依指路牌而行。'],core:'第198节说，单靠再添加一种解释，不能让规则获得最后支撑，因为解释也需要被使用。作者没有由此推出任何行动都算遵从，而把指路牌与行动的关系放回训练及持续习俗。因果历史说明怎么形成反应，习俗背景则让反应能够被说成遵从或偏离。',more:'本节特别要保留“不应这样说”的纠正。开头“什么都能解释成一致”是异议，作者替换它的表述，而不是将它接受为彻底怀疑论结论。结尾也不仅谈训练造成行为，还说明作为规则遵从的活动所处的正常背景。',quotes:[['任何解释，都连同被解释的东西一起悬在空中','假如规则被抽离应用，另一串解释文字也会遇到同样问题。解释并不因为站在规则旁边就自动有更坚固地位。悬空图像针对这种奠基要求，不是说实际生活中的每个解释都无用。'],['只有解释，不能决定意义','“只有”限定了批评。解释可以有效，也能纠正误会，但其效果不是脱离既有技术的自我执行。把解释放回已学做法，就不必要求它独自承担一个无穷后退的终止点。'],['我受过训练','这交代指路牌为什么引起某种反应，作者随后还面对因果不足的反驳。不能在此截断，便说遵从就是被刺激造成的动作。训练的作用被保留，但它不是论证的全部。'],['存在持续使用、存在一种习俗','结尾增加的是实践背景：有稳定的用法，人可以按它做、学它、纠正偏离。一次相同方向的运动若没有这种背景，未必已经构成依牌而行。这里并非以习惯频率直接定义正确，而是说明规则活动如何有位置。']],problem:['想用解释为规则奠基，容易产生无穷后退：一条解释需要另一条解释，后者仍可被不同理解。若认为每次都必须有一个最后解释，便会觉得规则永远不能决定行动。作者质疑的正是这个只有解释才能确定使用的要求。','放弃最后解释，不意味着放弃区分正确与错误。指路牌与行动之间有教学、训练和习俗的联系。我们能够说明某人是否看懂、是否走错、如何改正，而不必先让所有解释获得一个完全独立于实践的根基。','本站补充：同样按下红色按钮，可能是在按警报流程，也可能只是试灯。动作相同还不充分，场合中的制度与持续用法有关。这个例子只帮助区分动作的因果发生与它作为某项规则行动的角色，不声称所有规范都是按钮程序。'],heading:'因果形成与规则遵从',concepts:['解释是实践中的工具，可以比较实例、改换措辞、指出差别。它不是一个能在零背景中自行发布意义的符号。因此，承认解释不独自决定意义，并不是贬低解释，而是让它在能够真正工作的地方发挥作用。','习俗是可反复进行、学习和辨认的活动背景。它不是说人因经常如此就永远应该如此，也不是说每个动作都必须有人现场监督。即使一个人独自看牌走路，活动仍可属于已存在的用法；原文下一节将继续阐明这种语法关联。'],headers:['层次','可以说明','尚未单独说明'],rows:[['解释文字','怎样改述规则','解释自身为何无需使用'],['训练历史','反应怎样形成','何以算遵从而非偶合'],['持续习俗','规则行为的正常位置','每项具体选择的全部原因']],steps:['先改写开头异议：不能从解释可变化直接推出一切都合规则，而应看到解释本身不具有独立奠基地位。','再以指路牌要求一项具体联系，避免争论停在抽象的规则与行动两个词之间。','随后引入训练并正视因果反驳，说明作者没有只用反应机制取代规范概念。','最后指出持续使用和习俗。它们让依牌而行成为一种可识别活动，并为下一节的规则、命令、交流与技术提供连接。'],against:['本节反对只在解释链内部寻找意义的最后基础，也反对以解释不能独自奠基就宣布所有行为等价。','它不反对解释、训练或原因研究。不同工作可以相互支持，却不能把一种因果说明冒充对遵从规则的全部概念说明。'],views:[['从教学看','示范和纠错往往帮助解释发生作用。不能把它们当成语言之外无关紧要的附带条件，随后要求文字单独完成教学。'],['从规范看','遵从、偏离与偶合需要活动背景。一条路径在物理上朝同方向，不等于在每个场合都执行同一规则。'],['从哲学看','停止解释后退，不必寻找一种不可言说的最终事实。它可以意味着看见解释作为工具嵌在实践中，而非悬浮其上。']],warn:[['不是任何行动都符合规则','这句话在原文中被纠正。作者的回答恢复习俗背景中的区别，并非取消区别。'],['不是遵从等于条件反射','结尾明确超出因果说明。漏掉习俗一句，会把论证缩成作者已回应的立场。'],['不是习俗永不可改变','我们可以改路牌或改制度；改变本身也有可说明的做法。持续背景不等于永恒不变。']],summary:'解释不能脱离实践独自奠基；指路牌的规则作用涉及训练与持续的习俗。'});
study({id:199,short:'规则与技艺',title:'一个孤立动作，已经能叫作遵从规则吗？',sub:'把规则、命令、交流看成习俗，再理解掌握技术。',tags:['习俗','规则','技术'],link:'承接198节持续用法；200节测试动作相似与游戏辨认的关系。',text:['我们叫作“遵从一条规则”的事情，能不能是仅有一个人、在一生中仅做过一次的事？——这当然是在说明“遵从规则”这个表达的语法。','不可能只有一个人仅仅一次遵从过一条规则。不可能只有一次消息被传达、一个命令被给出或被理解，等等。遵从规则、传达消息、给出命令、下一盘国际象棋，都是习俗，即惯例、制度。','理解一个句子，就是理解一种语言。理解一种语言，就是掌握一种技术。'],core:'第199节把遵从规则、交流、命令和下棋置于可反复的习俗背景。一个完全脱离这种背景的孤立发生，不能只凭动作外形就承担这些名称。理解句子与掌握语言技术相连，不必被解释成脑中发生一件意义物的接收。',more:'原文明确称其为语法说明，不能当成统计报告，说现实中每项行为都必须发生两次。它也不是禁止独自按规则行动；重点是活动的可理解背景不能被缩成一个没有来历、没有继续可能的孤例。',quotes:[['这个表达的语法','作者已经限定问题类型。不是调查历史上最先一次命令是谁发出，也不是测量遵从规则至少需要几个人。它考察什么使一项行为在我们的用法中被辨认为规则遵从，以及这些名称如何与持续活动相连。'],['只有一个人仅仅一次','这一极限设定将惯例背景全部抽空。不能拿一个已经在社会中学会棋的人独自下一步当作反例，因为那里早已保留相关规则技术。问题不是此刻现场是否有人，而是行为能否与任何可重复实践完全隔离。'],['都是习俗','习俗不是只指未经反思的传统，也包括命令、交流与有明确规则的游戏等。它强调活动有学习、重复、纠正、继续的正常位置。把这句话改成习惯次数决定正确，会误把概念背景缩成频率统计。'],['掌握一种技术','技术在这里不是狭义工程操作。理解语言涉及会使用、会回应、会在相关场合继续，而不是只收藏词与对象的配对。掌握可以有深浅，句子的理解也依其在语言活动中的位置得到说明。']],problem:['若把规则看成一个独立对象，似乎某次孤立行动只要与对象相配，就已经是遵从。可什么算相配，前面已显示不能靠又一件解释对象自行保证。本节让我们看见遵从本身是一种有反复背景的活动名称，而非给任意动作加上的神秘属性。','类似地，一串声音是不是命令，不只看波形或说话者内心的某种感觉。给命令、接受命令、误解和纠正等联系，使声音在活动中有此角色。完全抹掉这些联系，再问一次声音为何具有命令性，就会要求一个原本未被需要的隐藏赋义过程。','本站补充：一个已学会棋的人在旅途中独自研究残局，仍可按棋规行动。他不需要别人当场批准，因为背景技术已经存在。这个例子用于排除孤独行动不可能的误读；它不是对所有可能私人语言争论作一次性定论。'],heading:'可重复背景与孤立发生',concepts:['可重复不等于事实上必须已重复某个固定次数。它表明活动属于一种能被继续、比较、学习的做法。规则可以第一次用于一个新数，命令也可以第一次用于一种新任务；这种新颖仍不同于完全没有用法背景的绝对孤例。','掌握技术让意义的说明与能力的语法相连。一个人能理解新句子，不必先背过这句具体组合；他有能继续运用的语言掌握。作者不是用动作列表穷尽人的全部理解，而是阻止把理解封闭成一个与一切继续使用无关的私有事件。'],headers:['情况','保留的背景','不能混同'],rows:[['独自算题','已学的计算技术','无任何可重复背景的孤例'],['第一次执行新命令','命令与执行的制度','声音自身神秘变命令'],['理解新句子','语言中的相关掌握','逐句私藏意义对象']],steps:['开头提出极限问题，随后立即说明这是语法问题，防止读者走向人数与次数的经验统计。','中段把规则遵从与交流、命令和下棋并列，使持续活动的共同位置变得可见，而非只在规则一词里寻找实体。','末尾转向句子和语言理解：理解不是与实践隔开的瞬时物，而与掌握可继续的技艺相关。这个回接也呼应150节知道、能够与理解的亲缘。','下一节将用陌生动作检验游戏辨认。因而本节还不能被压缩成只要有一群人的重复就有同一种规则；活动怎样被识别仍需要更具体的比较。'],against:['本节反对将遵从、命令和理解看成能够脱离全部惯例背景的一次性内在赋性。一个孤立感觉不能独力规定这些活动名称的全部意义。','它不反对个人独处时继续规则，也不声称一切制度都需多数票随时认可。公共背景与现场审批是两件不同的事。'],views:[['从交流看','传达不是仅把声音排出体外。消息能够被听懂、误听、转述或回应，这些联系帮助说明何谓一次传达。'],['从学习看','技术能够被新应用检验，却不等于训练时已经逐一列出全部未来实例。掌握与有限教学相连而不被穷尽为固定清单。'],['从规范看','制度背景使正确与错误有位置，但具体标准仍要在各自活动中说明。不能以习俗这个总名称直接替代所有差异。']],warn:[['不是孤独者无法遵从','一个人可以独自按已学技术做事。原文的极限设定抽掉的是全部习俗背景，而不只是旁观者。'],['不是至少重复两次的定律','作者明确说语法。不能把它改成经验上的最低次数要求。'],['不是技艺只指身体熟练','语言技术还包括解释、判断、回应和区分。将其缩成机械动作会丢掉本段意义。']],summary:'遵从规则与理解语言有可重复的习俗背景，不能由无背景的一次孤立发生独力说明。'});
study({id:200,short:'喊叫跺脚算下棋吗',title:'能翻译成棋步，就一定是在下棋吗？',sub:'以陌生动作测试形式对应与游戏概念的关系。',tags:['游戏','对应','实践'],link:'承接199节习俗背景；201节以后将继续规则与解释的困难。',text:['当然可以设想：在一个不认识游戏的民族中，两个人坐到棋盘旁，走出一盘国际象棋的棋步；甚至伴有一切心理现象。如果我们看见，会说他们在下棋。可是，现在设想：一盘棋按某些规则被翻译成一系列我们不习惯与游戏相联系的行为，例如喊叫和用脚跺地。那两个人不以我们熟悉的形式下棋，而是喊叫、跺脚；这些过程能按适当规则翻译成一盘棋。我们还会倾向于说他们在玩一种游戏吗？又凭什么有权这样说？'],core:'第200节用棋步与喊叫跺脚的对应，追问辨认游戏时凭什么。形式上可翻译成棋局，并未自动替我们说明这些行为在生活中的角色；熟悉外形和熟悉心理伴随也不是未经检查的最后标准。原文以问题结束，要求比较，未直接裁定陌生形式永远不能构成下棋。',more:'这里有两个设想，不能跳过第一个。先让我们面对看起来完全像棋的行为，再改变外形，只留下可以建立的对应。这个移动让日常判断的依据成为问题，而不是给出一条“凡相似皆下棋”或“凡陌生皆非游戏”的判定公式。',quotes:[['甚至伴有一切心理现象','加入心理伴随，防止读者用缺少内心感觉立即排除例子。作者不否认体验，却提醒我们：仅列出体验仍不能替代对活动的整体描述。若心理现象也被设成全部相同，游戏判断究竟依赖什么就更值得比较。'],['我们不习惯与游戏相联系','陌生性属于我们的识别习惯，不自动证明行为没有游戏结构。反过来，存在一种形式对应也不自动证明这些行为在当事人的活动中就是一盘棋。作者让两个方向的快速推论同时变得不稳。'],['按适当规则翻译成一盘棋','翻译需要指定对应规则。这个条件比单纯外形相似更强，却仍可继续追问：对应在何种活动中使用，是否服务于游戏，行为者怎样学习和继续。原文没有在此把这些问题全部回答，而是给出考察的入口。'],['又凭什么有权这样说','最后问的是判断理由，不是要求政治许可。我们凭何概念联系把这称为游戏？保持问号能防止把本节改写成作者已经给出的机械必要条件。它也使前节习俗概念继续接受具体实例的检验。']],problem:['一个复杂行为序列可与棋局建立形式对应，但形式对应与活动身份是否同一？若任何可对应的序列都算下棋，游戏概念可能失去原有辨识作用；若只有常见棋盘动作才算，又会排除可想见的新形式。作者用这个张力检查判断，而非立刻给出总定义。','心理伴随也不能简单补足外形标准。第一种设想刻意保留全部心理现象，仍把行为置于不认识游戏的生活背景。我们容易按熟悉画面称其为棋，但随后陌生化的版本让这份自然判断需要说明。经验熟悉与概念根据不应未经检查就等同。','本站补充：一种游戏可以把走子改成口头报坐标，人们仍可学习其输赢与纠错；同时，一段天气记录也可能被人为编码成某盘棋。前者与后者为何不同，不能只靠都有编码对应来回答。这些补充不是作者的直接结论，而是展开其结尾追问的比较材料。'],heading:'形式对应与活动角色',concepts:['对应规则能保存某些结构关系，却未必保存活动的全部用途。我们可以在纸上把不同序列一一配对，而那些序列在各自生活中的角色仍不同。因此应说明翻译保留了什么、忽略了什么，而不是把可翻译这个词当作活动同一性的自动证明。','游戏概念也不应被固定在熟悉外观上。改变棋子材质、用盲棋或其他媒介继续，都可能仍处于棋的技术中。这类实际或可能比较提示我们寻找活动联系，而不是从陌生动作直接判非游戏。本节的开放问题容许我们继续比较，未把某个外形特征设为不可替换本质。'],headers:['考察条件','有助于说明','未必独自决定'],rows:[['熟悉棋步外形','我们为何立即认作棋','活动全部角色'],['相同心理伴随','体验不是被简单排除','游戏身份的唯一标准'],['喊叫跺脚可译棋局','形式关系能够对应','当事活动必是下棋'],['游戏习俗背景','学习、继续与纠错','一条包办全部实例的定义']],steps:['先设定外形与心理都熟悉的棋局，但置于不认识游戏的群体中，使生活背景与可见现象被暂时分开。','再把棋局按规则译成陌生动作，保留结构对应并改变直观判断的诱因。','最后问我们是否仍称它为游戏及凭什么。问法要求读者说明根据，而不是只报告“我看着觉得不像”。','接回199节时，可以看到习俗背景并非一个只需念出的答案。怎样在这些具体例子中说明惯例、技术与游戏关系，仍需逐项展示。这是本站对前后节联系的说明，不把后续201节的回答提前当成本节原话。'],against:['它反对未经检查就用外形、心理体验或形式可译性中的任一项，作为判定游戏的独立最终标准。','它也反对只因行为陌生便否认可能的游戏身份。若新形式进入可学习的游戏实践，判断可能不同；本节没有将这种可能预先封死。'],views:[['从形式看','编码能够保留关系，但编码本身也是一种活动。应问谁以何目的使用对应，不能把形式关系从所有用途里抽出再让它单独决定名称。'],['从文化看','陌生行为需要理解，不能只按我们的外形习惯分类。原文的思想实验不是一项关于任何真实民族的观察报告。'],['从精读看','问句结尾使论证保持开放。初学者应学会说明问题怎样被推进，不必为了每节都有结论，就替作者制造一个尚未出现的定理。']],warn:[['不是喊叫绝不可能下棋','原文没有给出这个断言。不能把我们的最初不习惯当成作者的绝对标准。'],['不是一切编码都算游戏','存在对应还需要说明活动角色；本节正要求追问这样称呼的根据。'],['不是心理体验被否定','第一设想明确加入心理伴随。作者检查其解释地位，而不是取消体验事实。']],summary:'可翻译成棋局与作为下棋活动之间的关系，需要在具体实践中说明；本节保留这个追问。'});
// 各节分别展开尚未说清的比较步骤，避免用通用段落替代精读。
const depth={
185:[
'这里有一个容易漏掉的逻辑差别：由有限结果不能逐项列出无限未来，并不等于未来的正确性没有标准。前一句说明考查的形式，后一句却是关于整个规则活动的强断言。两者之间没有直接推论。教师不需要先看见无限步骤才有资格说1002正确；但若想说明这种资格，不能再把它画成看见了无限步骤。作者的例子正迫使这个平常被略过的区别出现。我们应当从命令怎样教、怎样响应、怎样纠正继续分析，而不是把形式上的有限性扩大成对一切理解的否定。这样，也能理解为什么开头仍称学生按通常标准已经掌握：标准并不因为可能出现例外就自动失效。',
'还要比较异常的两种处理。一种是学生立刻说自己写错，改为1002；另一种是他认真说自己一直如此理解，且不能通过旧例子被带回。前者仍在熟悉纠错程序中，后者才使程序的背景成为问题。本节选择后者，不是为了规定每个错误都这么深，而是把最容易被视作自动的环节暂时取走。对学习过程作这样的变形，会让我们发现“再解释一次就能懂”本身也是对人类反应的期待，不能被当作符号固有的物理作用。与此同时，异常者的认真也并不建立另一项规范权威：诚实描述他怎样继续，与认定他遵从了我们的加二，仍是两种判断。'],
186:[
'原文从“正确遵从”起问，比从“怎样产生下一答案”起问更严格。一个心理机制可以稳定地产生某串数字，但是否按给定命令继续，还需要已有计算标准。若把机制的稳定性当作规范性，任何稳定犯错的人都将自动成为正确。直觉解释容易藏起这个转换：它既被说成一种发生在心里的体验，又被说成必然正确的裁判。作者不需要否认体验存在，只需提醒我们，对体验的正确性仍有问题可问。于是，内心确信和规范符合之间的距离不能靠给体验加上直觉这个名字来消除。这也说明为何本节没有建立新的直觉主义数学基础。',
'一次命令可以概括无穷情况，但概括的语法不应被改写成无穷次心理动作的压缩。我们说所有偶数，并不表示曾在心里逐一数完它们；同理，教师意指一条数列，并不表示在某个非时间媒介中写完数列。反过来，指出没有写完，也不是反驳所有偶数这类表达。问题在于概括如何在技术中被用，而不是它有没有秘密完成逐项列举。末尾“决定”一词仍须在这一背景下读：新的位置要被实际处理，不是因为作者宣布它在数学上没有要求，而是因为不能用过去意向的幽灵演算代替当下继续的说明。'],
187:[
'对自己过去能力的说明，经常与对过去事件的报道共享相同的时态。正因为表面句法相似，才会有本节的诱惑。我说昨天就会解这道题，并不等于昨天已经解过这道题；若昨晚第一次学会相关算法，便可能今天认出自己昨天已经具备解题能力。这个本站补充并不要求所有知识都能还原成算法。它只展示一个熟悉区分，让“已经知道”不再强迫我们寻找当时出现的一幅答案图像。把这一区分用回教师身上，他的主张就不必成为一个关于未知心理事件的猜测，而可以继续作为对当时掌握状况的正常说明。',
'救人反事实也不是万能证明。一个人可能夸大自己当时的勇气，我们当然可以怀疑他的判断。但即使存在这类怀疑，仍不能推出这种话必定是在回忆一次真实跳水。同样，对计算教师也可以问他当时是否真的掌握加法，却不该把问题偷换成能否找到每个未来过渡的心理记录。本节明确不怀疑他会答1002，所以当前要解除的是一种错误解释，而非一个事实争议。这个安排使论证更有力：在承认普通主张的情况下，仍能撤回附加的内在预演图像，无需靠否定全部日常知识来获得结论。'],
188:[
'“其实已经做了”保留了完成动作的语气，“甚至在思想中做之前”又撤去了最后一种熟悉完成方式。这个组合不只是诗意夸张：如果它被用作规则效力的解释，就要承担说明什么算完成的责任。读者可以比较正常的完成说，例如计划已经写好、证明已经做完、训练已经结束。它们各有可辨认的对象和完成条件；本节的特殊完成却在排除这些条件后仍要求同一种确定感。这样比较，并不证明凡不可见都不存在，而是让我们看见当前解释借用了哪些普通标准，却又不肯接受这些标准的约束。',
'心灵先行的图像还有一项代价：它似乎把未知未来变成已走过的过去，因此理解被画成一种非凡记忆。可是若所有应用必须先被某种灵魂演算完成，我们仍可问那次演算依据什么规则正确进行。若又要另一项先行意指，问题就重复了。作者不在这里展开一条形式化无穷后退证明，但这个回问有助于看出图像没有真正增加解释力。它只是把身体尚未完成的工作委托给一个没有明确使用标准的代理者。将这项委托撤回，才能继续问公式、训练和应用的实际联系，而不是不断为代理者添加新能力。'],
189:[
'公式的种类与使用方式须一同出现，还因为单看字形不足以交代变量范围和运算约定。例如同一个等式在不同系统中可以有不同的背景规定；本节并未逐一讨论这些系统，却已明确把数学证明放在“某一系统”内。这一限定阻止我们从一个熟悉算式直接跳到对符号普遍本质的结论。若要问一个式子是否给出唯一值，就应清楚给定什么、允许哪些值、按哪些规则演算。做到这些，问题可以严格；不做这些而追问它是否真正决定，反而可能只剩对严格性的空泛要求。哲学澄清不降低标准，而是要求说明标准在哪里工作。',
'还应区分两类句子的认识作用。“这里写着一个决定y的式子”可以因看错纸面而错；“这类式子对给定x决定y”则可能是在说明已采用的分类或提出数学命题。二者都含决定，却不因此有完全一样的判断根据。把它们排列开，有助于看出一个总的真或假回答为什么不够。原文最后提到教学考查，进一步说明同一问句还可以用来查看学生是否掌握术语，而不在此寻找新定理。这些差异不意味着语言任意混乱，恰恰表明熟悉活动中已有稳定区分，只是哲学概括容易把它们盖住。'],
190:[
'如何看出一个陌生符号被用作平方，可以由具体取值展开：在通常数值下，平方与两倍未必每次给不同结果，例如某些输入恰好重合。一次相同输出因此不足以判定运算身份；我们还会看更多相关例子、表达者的说明以及他如何纠正误算。这个本站补充不是增加新数学理论，而是让“标准”避免被误解为看一次动作就能机械读心。判断意思是在一组相联系的做法中进行，而不是把每次行为孤立登记后再统计多数。这样既保留判断的公共依据，也能说明为什么一个偶然笔误不必改变公式的意思。',
'陌生记号的例子还表明，意指与符号约定可以有创造性。表达者不必先等整个社会使用新符号很多年，才有资格提出清楚约定；但他得把新记号接到已经能说明的技术中。若说这里用这个符号代表平方，我们便可按照平方的做法继续；若说代表乘二，又有另一组说明。创新不等于凭内心印章赋予一个完全脱离所有技术的对象。作者因此能同时保留个人的说明和一贯使用的标准，并避免落入只有集体长时重复才可能有意义的极端解释。'],
191:[
'相互交错的图像并不一定在意识里以清楚画片出现。它们也可以是表达中的隐含要求：意义像一件物品，应可被完整拿到；理解像一个瞬间，应当现在全部发生；使用像一条无限道路，又尚未全部走过。当三种安排被强行要求同时满足，一瞬拥有无限未来便仿佛成了唯一答案。作者的工作是把这些要求拆开，看它们原来各自怎样工作。这样就不需要先否认任何正常理解经验，也不必证明人有绝对不带图像的观察。比较的意义是松动某个组合的独占，而不是取消所有比喻。',
'可以问，一个主张若拒绝一切普通范例，却坚持自己比普通理解更真实，究竟允许怎样的说明算成功。这个问题不在于为哲学设一套简单经验主义禁令，而在于让主张承担区别自己的责任。如果对方能展示新的用法与相关比较，讨论当然可以继续；若只反复说更直接，却无法交代增强在哪里，哲学家就应追踪表达的诱惑，而非假定强烈确信本身已经证明特殊事实。第192节将这一动作命名为最高级，正是承接这种对表达责任的检查。'],
192:[
'哲学最高级的危险，不只在词语夸张，而在它改变了评价解释的标准。原先用法清楚、能够回应困惑的说明，被说成还不够真正；对方要求一种排除所有可能背景的最终说明，却又不说明怎样识别它。于是任何正常答案都先被判为表面，未找到最终答案反而像深刻的证据。这种安排会使任务无法完成，但无法完成并不必然表示对象高深，也可能表示要求没有给出可辨认的工作。指出这一点，是为了让研究重新获得可以继续的方向，而不是以嘲讽代替论证。',
'“最高级”也不能被用作一个万能驳斥词。若另一个思想家说自己的理论更一般，我们需要检查其比较范围、推导与实例，而不能仅因有更字便宣布它受骗。同样，一项新技术可以比旧技术更精确，数学概念也可以获得更强定义。本节只针对前节那个没有范例却增强语气的要求。将这项边界保留下来，解释才与作者的方法一致：具体诊断具体诱惑，既不把语言当作全然无害，也不把所有抽象表达都当成病症。诊断的力量来自展示，而不是来自术语声音够坚决。']
};
for(const [id,paragraphs]of Object.entries(depth)){window.ESSAYS[id].concepts.push(paragraphs[0]);window.ESSAYS[id].argument.push(paragraphs[1]);}
const moreDepth={
187:['“当时会这样回答”与“后来果然这样回答”也需要区别。前者是在说明过去掌握状况，后者可是一件新发生的事实；二者能够相互支持，却不必完全同义。作者使用救人类比，不是要求把知识还原成未来行为频率，而是让一种无须当时实际演出的过去归属变得清楚。'],
188:['还有一项反向检验：如果心灵早已完成一切，我们怎样知道它完成的是加二而不是学生那种分段增加？如果答案仍须通过怎样理解命令、怎样继续来说明，那么超前演算并没有提供独立标准。它只是把需要澄清的技术重复画进另一个空间，却让重复显得更神秘。'],
189:['本节用相同输入获得相同输出说明训练的稳定性，却没有将数学唯一性定义成每人事实上从不犯错。否则一个偶然笔误就会改变公式的类别，这显然不是例子的工作。理解这个限定，才能在保留操作背景的同时，不把规范分类混同于行为一致的经验统计。'],
190:['例如在输入二时，平方与两倍都得四，所以单独这一次结果不能完全区分意思；若换到输入三，通常便可区分九与六。这个本站补充使判断标准更具体，但也不说明必须把所有输入测完才允许理解。相关说明、教学背景与可继续的操作共同发挥作用。', '将意指当作心理印章还有一个问题：若每种运算都需再用一个内在标记选定，我们又得问这个内在标记怎样选定运算。符号问题于是只是向内移动。原文让我们看一贯使用，是为了终止这种错误任务，而不是声称脑中没有任何可研究过程。'],
193:[
'抽象图解并不是对真实机器的一次草率预测。教师展示齿轮传动图时，通常是在让学生按图继续，而不是保证任意材料在任意温度都不熔化。若读者不断以熔化可能反驳图解，可能误认了任务；若教师用图解的确定性保证真实装置永不失效，也同样跨越了任务边界。原文两次提到变形，正帮助我们辨认这两个相反误用。哲学困难不应通过在二者之间选一个永远正确者解决，而应说明此时究竟在做哪一种工作。只有任务确定，所谓完全决定才有可检查的内容。',
'数列第二十五项的括号例子也不可省略。我们可以用生成方式指定一个数，而不先把该数的所有表示摆出；会这项技术的人能够继续算出它。机器图类似地可以作为一系列图的起点。这个比较并不证明机构运动与数列计算的全部性质相同，只让共同的表示作用可见：起点能按学会的规则引出后续。若把这种能够引出改画成后续已是起点内部的东西，就重演抽屉图像。比较本来用于解除神秘性，不能反被当成又一项神秘容纳关系的证据。',
'原文最后承认真正的区别，使本节不落入一切只是经验预测的还原。设计表示中的约束与实物运行的可靠性，可以有不同判断标准；前者若出问题，可能是读图或规则不清，后者若出问题，可能是材料或条件变化。实际工程常把两种工作连接起来，但连接不等于取消区别。理解这一点，才能既承认规则表示的明确，又不把明确误认成一种比真实钢材更硬的材料。作者没有替工程学作新发现，而是限制哲学家对工程表达的过度解释。'],
194:[
'本节对经验句与概念句的并列，可以帮助读者分清两种疑问。我可能不知道这个空隙能否让轴销转动，这需要试验；但若已经说这是某一特定运动的可能性，再问它是不是另一个运动的可能性，可能已换了描述本身。后者未必是一项像前者的实验任务。由这种差异推出一种超经验物件，是多走了一步。作者要揭示的正是这一步，而非否认经验研究能判明运动条件。把两个疑问各放回其场合，原先似乎神奇的关系就不必再被实体化。',
'“拥有”一词也不是只能用于实物所有权。人有机会、计划有缺陷、机器有某种结构，都有各自正常说法；我们并不会一律去找被拥有者躺在哪个容器里。这里列举的其他表达为本站补充，用来说明主谓外形不能直接规定本体结构。机器有运动可能性同样需要具体说明，而不是因为语法类似有零件，就断定另有一类微小影子零件。将这样的表面相似拆开，才是在做本节要求的语法比较，而非发明一个替代可能性实体。',
'需要注意，作者不是用一个新的可能性定义结束讨论。若把“可能性就是用法”当成总公式，再要求所有可能性实例都与之相同，就会把方法提醒变成另一套单一本质。本节细读的价值恰在逐条展示：图像展示怎样被误解，已有一词怎样被误解，非经验联系怎样被误解。每条都有自己的转换步骤。学会辨认这些步骤，比背出影子不存在更有帮助，因为后者若脱离实际误推，只会成为又一个不允许别人继续追问的结论口号。'],
195:[
'裁缝故事还说明，知道一个动作词不等于知道它在所有搭配中的用途。孩子也许见过针线操作，却把缝衣服的表达拆成只有线的制造技术。误会不是一定缺少更多线的知识，而是整项活动被错误重组。对理解未来使用的哲学表达，也可能发生相同重组：规则与技术被取走，只留下一个瞬间动作，再问这动作如何生产全部未来。我们需要恢复活动的联系，而不只在动作内部寻找更强大的微观阶段。例子因此是结构比较，不是一个嘲笑幼年思维的笑话。',
'说其余正确，并不说明所有原句字面解释同时正确。普通使用中有某种意义上的预先性，正因为我们会依据规则继续、会在出错时纠正，而不是因为未来已经成为当前事件。作者把特定表达的正常工作保留下来，便无需为一项虚构的当前存在辩护。读者也可据此检查自己的解释：若解释一方面承认未来没发生，另一方面坚持它以绝对更真实方式发生，是否仍在制造原文所说的奇怪语言游戏？这个回问帮助诊断，不替所有时间哲学争论预先作结。',
'语境说明还应接受检验。我们若说某句话在实际活动中正常，就应能举出谁何时说它、别人怎样回应、何种情况算误解。不能只凭解释者愿意给它一种好听意义便宣布问题解决。原文给裁缝故事，是把这种检验直接展示出来：材料与技艺重新出现后，孩子要求的奇迹便不再必要。类似地，教学、规定和掌握重新出现后，意向中包含未来的说法可以有普通解释，不需要再托付给一种无法举例的特殊过程。'],
196:[
'本节的两个括号例子有共同形式，却不应被压成同一学说。把时间当介质，突出了承载与流动图像；把心灵当特殊存在，突出了一个类似物体却不可见的主体。二者都可能在正常表达被字面化后产生，但各自需要不同材料来澄清。作者用短句让比较开始，而非宣布只要说语法误解就完成所有分析。若解释者不愿继续展示具体差异，也可能把方法名称当成了新的神秘原因，仿佛一切困惑都由同一个叫语言的东西自动制造。',
'读者可以用一个检查次序避免滑向对象化：先复述原句在熟悉场合怎样说，再指出眼前追问额外要求了什么，最后观察这个要求是否仍有明确判断条件。这个次序是本站为学习整理的方法，不是原书本节逐项列出的程序。它让我们不因句子难懂就急于宣布它无意义，也不因它带来强烈不安就立刻承认一个隐藏实体。谨慎的工作位于两者之间：承认困惑存在，并且要求描述困惑如何形成。这样，解除一种假任务并不妨碍保留真正可调查的问题。',
'若确有一种经验过程尚未理解，正常做法是说明可观察现象、提出假设并考察依据。本节并不撤销这套研究。它问的是，哲学家是否在还没有形成这种任务时，就把一个语法位置当作过程证据。例如仅因理解可说发生了，便要求在意识中找到一件具有特殊形状的理解事件。一个词能够进入发生句，并不已经证明它与所有其他事件有同一结构。把这一步说清，便能看见为什么作者既不需要否认心理事实，也不需要为每种心理词发明一件对应物。'],
197:[
'原文说毫无疑问我想下棋，不是说任何第一人称报告都不可错，而是在当前场合允许这种确信。随后它追问：为什么我们非把确信解释成瞬间装入全部规则，才觉得它有根据？教师可以问一个初学者是否懂规则，熟练者却不必每次邀请都参加这场考查。这些正常差别显示，意向表达有不同场合与判断位置。若把它们统一改成对内在内容物的检测，就会丢失这些差别，再以丢失后的空白证明需要一条神秘联结。作者要阻止的是这个循环，而不是取消自我理解。',
'游戏规则目录也不是在每次意向中被默读的剧本。一份目录可以在需要时查询，教学可以使人会用，实际对局又使规则持续发挥作用。三者的并列显示联系分布在活动中，不能被收缩为某一个心理画面。我们可以设想有人没看过正式规则书，却通过下棋学会相当多；也可以有人熟背文字却不会判断局面。这些本站补充让理解目录与掌握技术的区别更清楚，不用于否认明确规则的重要性。原文保留目录，同时将其放进教学与实践的更广联系。',
'“我想玩什么”与“稍后实际发生什么”还可能出现正常差距，例如有人改变主意或中途被打断。若按原文批评的图景，意向早已把全部未来事件放进自己，便难说明这些差距；若把意向只当预测，则又不能说明人何以能在改变主意之前清楚表示打算。实践中的意向表达不必满足这两个极端模型。它可以现在有确定内容，而后来行动仍可偏离。确定内容的说明要回到所意图活动怎样被识别，而非要求未来必须已成为过去。'],
198:[
'把解释说成悬空，不是给每条解释加上真假不可知的标签。悬空形容的是一种被抽离使用的奠基姿态：我们把规则和说明排成两串文字，期待后一串本身能使前一串获得行动方向。可若读者不会相关技术，两串文字都可能不帮忙；若会，说明可能马上奏效。这个差别表明，解释的作用不能仅从文字彼此相接中读出。指向实践，也不是神秘地让动作替文字发声，而是展示解释怎样在示范、纠错和继续中成为一种工具。这个展示可以具体而严格，不必停在泛称习惯。',
'因果反驳之所以重要，是它避免将规范性偷换成心理规律。一个人可能被训练得见箭头总向右，却在某次环境中只是机械反应；我们若说他依指路牌而行，还涉及牌的用法、道路安排和活动目的。原文没有要求每次都在头脑里反思所有背景，但背景不能因此被视为不存在。持续用法为反应提供一个可理解的位置，使走错、误认和偶然同向能够区分。于是，训练与习俗不是两个互相竞争的秘密原因，而是在不同问题中说明联系的不同方面。',
'不能把结尾理解成只要某事经常发生，就立刻成为规范。雨经常落下并不因此遵从一项人的命令；人经常误读某牌，也不必因此使误读自动正确。这里的持续使用属于一种会教、会纠正、会辨认的技术活动，而非纯粹事件频率。这个限定由本站补充展开，帮助读者保留因果与规则的区别。否则，用习俗解释规范又会退回单纯统计，恰好重现原文已经正视的反驳。下一节的制度与技术表达，使这一背景更明确。'],
199:[
'原文把消息、命令和棋局并列，并不是说它们必须共享一个隐藏本质。并列的目的在于让一项容易忽略的背景出现：这些活动都不能只靠一次身体事件的外形说明。消息涉及可理解的传达，命令涉及被执行、拒绝或误解的可能，棋局涉及可继续的游戏技术。它们的具体标准不同，却都使纯粹孤立发生的设定显得不足。因而本节与前面家族相似的方向并不冲突。通过比较显示联系，不等于给一切行动重新寻找一个单一本质。',
'“制度”在这里也不只指有书面章程、管理机关和法律认可的组织。语言中的请求、回应和计数，可以在没有正式办公室的生活中拥有稳定做法。若把制度理解得过窄，就会误以为作者声称凡未登记的规则都不存在；若理解得过宽，只要动作重复就叫制度，又会失去规范区别。恰当读法应回到例子：人如何学习，何时可继续，发生偏离时怎样理解和处理。本站如此展开词义，是帮助辨认原文的背景要求，而不是为一切制度制定必要充分条件。',
'末句“理解一个句子，就是理解一种语言”也不是说每次理解都要求精通整种语言全部领域。一个初学者可以懂某类句子，而在别的情形不懂。这里强调句子不是意义孤岛：它的理解与相应语言技术相连。若把语言掌握再解释成脑中已完成全词典和全语法，便会把作者已经批评的无限容纳要求搬到更大尺度。技术可以有局部、层次和继续学习的空间；它需要背景，却不要求一个无所不知的最终状态。'],
200:[
'第一种设想里，我们自然会说他们下棋，这个自然反应本身也是材料。作者没有立刻判它错误，而是用第二种设想改变可见形式，观察判断是否变化。若变化，我们便要问：先前依靠了什么？若不变化，也要问：为何对应足够让我们继续称其为游戏？无论回答哪边，都不能只把自己的倾向当作无需说明的最终根据。这样的问法使读者参与概念比较，并非安排一道有唯一标准答案的课堂测验。网站解释应保留这份开放，避免替原文预先裁定所有陌生游戏。',
'对应还涉及被选择的尺度。动作序列可以只与棋步的一部分关系对应，也可以保存走子次序、胜负和合法性等更丰富结构。原文说按适当规则可翻译，却没有在此列出一套完整判准。学习者可以沿这个方向继续问，但不应把我们补充的编码条件伪装成作者已经写出的结论。同样，习俗背景也需要具体描述：这些人是否把动作当竞争，能否教学，能否辨认某次偏离，都是可能的比较方向。它们不必被压成一张放诸所有游戏皆准的清单。',
'心理伴随的保留还阻止一种内外二分的捷径。我们不能说只是外面像棋，里面没有相应感觉，因为原文已把这些感觉也加进设定。可若又说只要内外都像就必是棋，第二个例子便追问形式改变后是否仍可如此判断。这显示哲学比较不是简单寻找最后一件遗漏的要素，再把它塞进定义；有时需要改变整个描述视角，去看活动在一种生活中怎样存在。这个联系呼应前面要求旋转考察的方向，却仍应由本节两个具体设想来支撑。']
};
for(const [id,paragraphs]of Object.entries(moreDepth)){window.ESSAYS[id].problem.push(paragraphs[0]);if(paragraphs[1])window.ESSAYS[id].concepts.push(paragraphs[1]);if(paragraphs[2])window.ESSAYS[id].argument.push(paragraphs[2]);}
// 为两节的关键限定补上直接说明。
window.ESSAYS[188].argument.push('因此，这幅先行图像并不只是无害的夸张。它一旦承担解释工作，就会把规则正确性的全部负担交给那个尚未说明的先行者。指出这一负担，才是把比喻放回适用范围的理由。');
window.ESSAYS[190].argument.push('本节恢复“这样决定”的说法，也要求读者保留回指。若把这样删去，原来的神秘意指就容易借结论重新进入。准确精读不仅看结论肯定了什么，也看肯定借助了前面哪些具体区别。');
})();
